    "car.f4v": "Shuttle train, ≈ 12 min",
    "chg.h1": "Electric vehicles & charging",
    "chg.lead": "Charging your electric car while you visit Zermatt, and how to reserve a charging bay.",
    "chg.p1": "The Matterhorn Terminal is one of the largest charging locations in the Alps, with 131 charging stations built into the covered car park. The stations deliver up to 22 kW (AC) with a fixed cable and a Type 2 plug, so most electric cars can charge comfortably while you are up in Zermatt.",
    "chg.h2a": "Reserving a charging bay",
    "chg.p2": "When you book, choose “Parking with e-charging station” instead of standard parking. That reserves a space next to a charger for the whole of your stay, so you don't have to hunt for a free unit when you arrive.",
    "chg.callout": "Choose “Parking with e-charging station” in the first step of the booking form to guarantee a charger for your dates.",
    "chg.h2b": "Paying for the energy",
    "chg.p3": "Your reservation covers the parking space and the charging bay. The energy you actually draw is billed separately at the station by QR code — credit card, TWINT, Apple Pay and Google Pay are all accepted — so you only ever pay for the electricity you use.",
    "chg.f1k": "Stations",
    "chg.f1v": "131, in the garage",
