    "chg.f4k": "Energy",
    "chg.f4v": "Paid at the station by QR",
    "trn.h1": "Getting to Zermatt",
    "trn.lead": "How the shuttle train connects Täsch and car-free Zermatt.",
    "trn.p1": "Because combustion-engine cars are banned in Zermatt, the last leg of the journey is by rail. The shuttle train runs between Täsch and Zermatt from early morning until late at night, roughly every 20 minutes, and covers the distance in about 12 minutes.",
    "trn.h2a": "Tickets & platform",
    "trn.p2": "The platform is right next to the car park — no street to cross, with lifts and ramps down to the tracks. The easiest way to get shuttle tickets is to add them to your parking booking; you can also buy them from the machines at the terminal or in a rail app.",
    "trn.callout": "Add your Zermatt Shuttle tickets in the same form when you book your parking — or buy them later from the machines at the terminal.",
    "trn.h2b": "Luggage & onward travel",
    "trn.p3": "There are baggage trolleys on both platforms, and many Zermatt hotels send an electro-taxi to meet guests at the Zermatt end. Leave a little buffer in high season, when trains and platforms are busy.",
