    "hero.title": "Réservez votre parking<br>à Täsch pour Zermatt",
    "hero.subtitle": "Réservez votre place au Matterhorn Terminal de Täsch et rejoignez Zermatt, station sans voitures, en navette ferroviaire.",
    "info.title": "Se garer et rejoindre Zermatt",
    "info.guarantee": "Zermatt est une station sans voitures. Laissez votre véhicule au Matterhorn Terminal de Täsch et prenez la navette — elle circule environ toutes les 20 minutes et atteint Zermatt en 12 minutes environ.",
    "info.process": "Réservez en ligne en quelques clics. Après le paiement, vous recevez un e-mail de confirmation. Votre plaque est enregistrée : grâce à la lecture de plaque, la barrière s'ouvre et vous entrez directement dans le parking couvert — aucun ticket à perdre.",
    "info.extra": "Le terminal compte environ 2 100 places couvertes et 131 bornes de recharge. Choisissez « Parking avec borne de recharge » au moment de réserver pour bénéficier d'une place équipée pour votre voiture électrique.",
