    "footer.legal": "© 2026 Täsch Parking",
    "footer.l.charging": "Vehículos eléctricos",
    "footer.l.train": "Cómo llegar a Zermatt",
    "book.step1": "Detalles del parking",
    "book.step2": "Billetes",
    "book.chooseOption": "Elige tu opción",
    "book.optParking": "Parking",
    "book.optCharging": "Parking con estación de recarga",
    "book.optParkingSub": "Plaza cubierta en el terminal",
    "book.optChargingSub": "Plaza cubierta + punto de recarga",
    "book.perDay": "día",
    "book.periodPh": "Elige tus fechas",
    "book.selectEnd": "Ahora elige la fecha de salida",
    "book.selectDates": "Selecciona las fechas de llegada y salida.",
    "book.day": "día",
    "book.days": "días",
    "book.maxHeight": "Altura máxima de los vehículos: 2,30 metros.",
    "book.priceHint": "Elige tus fechas para ver el precio.",
    "book.longStay": "Tarifa de larga estancia aplicada (desde 8 días)",
    "book.holderNote": "La confirmación de la reserva se enviará a este correo electrónico.",
    "gh.title": "Información del parking",
    "gh.lead": "Todo lo que necesitas saber para aparcar en el Matterhorn Terminal de Täsch y llegar a Zermatt sin coches — cómo llegar, recargar tu coche eléctrico y cómo funciona el tren lanzadera.",
    "gh.banner": "Zermatt es libre de coches. Todos los coches se detienen en Täsch: aparca en el Matterhorn Terminal y continúa en tren lanzadera o taxi.",
    "gh.car.d": "Llega a Täsch por la carretera del valle, aparca en el terminal cubierto y sube al tren. Ruta y límite de altura.",
    "gh.charging.d": "131 estaciones de recarga en el terminal. Reserva una plaza con cargador y carga el coche mientras estás en Zermatt.",
    "gh.train.d": "El tren lanzadera une Täsch y Zermatt en unos 12 minutos, aproximadamente cada 20 minutos. Añade los billetes a tu reserva o cómpralos en el terminal.",
    "gh.reduced.d": "Plazas accesibles cerca de los ascensores y acceso sin escalones al andén de la lanzadera.",
    "car.h1": "Llegar en coche",
    "car.lead": "Cómo llegar al Matterhorn Terminal de Täsch y dónde dejar el coche para Zermatt.",
    "car.p1": "Zermatt es libre de coches, así que todo viaje por carretera hacia el Cervino termina en Täsch. Desde el valle del Ródano sigue la carretera cantonal subiendo por Visp, St. Niklaus y Randa; el Matterhorn Terminal está justo al lado de la estación de Täsch, al final de la carretera del valle. Pon en el navegador «Matterhorn Terminal Täsch» y te llevará directo a la entrada.",
    "car.h2a": "Aparcar en el terminal",
    "car.p2": "El terminal es un aparcamiento cubierto de varias plantas con unas 2100 plazas. Al reservar online se guarda tu matrícula, de modo que la barrera se abre automáticamente al llegar y vas directo a una plaza — sin ticket de papel que guardar. Elige «Parking» para una plaza estándar o «Parking con estación de recarga» si necesitas cargar el coche.",
    "car.callout": "Reserva online antes de salir. Tu matrícula se reconoce en la barrera, así que te ahorras las máquinas de pago a la entrada y a la salida.",
    "car.h2b": "El límite de altura",
    "car.p3": "La altura máxima es de 2,30 metros: suficiente para turismos, familiares y la mayoría de los SUV sin cofre de techo. Los vehículos más altos, como las autocaravanas, no pueden usar el aparcamiento cubierto.",
    "car.h2c": "Del coche a Zermatt",
    "car.p4": "El andén de la lanzadera está a dos minutos a pie del aparcamiento. Los trenes a Zermatt sin coches salen aproximadamente cada 20 minutos y tardan unos 12 minutos; también hay taxis y lanzaderas eléctricas de hotel que recogen en el terminal.",
    "car.f1k": "Aparcamiento",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Plazas",
    "car.f2v": "≈ 2100, cubiertas",
    "car.f3k": "Altura máx.",
    "car.f3v": "2,30 m",
    "car.f4k": "A Zermatt",
    "car.f4v": "Tren lanzadera, ≈ 12 min",
    "chg.h1": "Vehículos eléctricos y recarga",
    "chg.lead": "Recargar tu coche eléctrico durante la visita a Zermatt y cómo reservar una plaza de recarga.",
    "chg.p1": "El Matterhorn Terminal es uno de los mayores puntos de recarga de los Alpes, con 131 estaciones integradas en el aparcamiento cubierto. Las estaciones ofrecen hasta 22 kW (AC) con cable fijo y conector Type 2, de modo que la mayoría de los coches eléctricos cargan cómodamente mientras estás en Zermatt.",
    "chg.h2a": "Reservar una plaza de recarga",
    "chg.p2": "Al reservar, elige «Parking con estación de recarga» en lugar del parking estándar. Así tendrás una plaza junto a un cargador durante toda tu estancia, sin tener que buscar uno libre al llegar.",
    "chg.callout": "Elige «Parking con estación de recarga» en el primer paso del formulario para tener un cargador garantizado en tus fechas.",
    "chg.h2b": "Pagar la energía",
    "chg.p3": "Tu reserva cubre la plaza de aparcamiento y la plaza de recarga. La energía que realmente consumes se cobra aparte en la estación mediante código QR — se aceptan tarjeta de crédito, TWINT, Apple Pay y Google Pay — así que solo pagas la electricidad que usas.",
    "chg.f1k": "Estaciones",
    "chg.f1v": "131, en el aparcamiento",
    "chg.f2k": "Potencia",
    "chg.f2v": "hasta 22 kW AC, Type 2",
    "chg.f3k": "Reserva",
    "chg.f3v": "«Parking con estación de recarga»",
    "chg.f4k": "Energía",
    "chg.f4v": "Se paga en la estación con código QR",
    "trn.h1": "Cómo llegar a Zermatt",
    "trn.lead": "Cómo el tren lanzadera conecta Täsch y Zermatt sin coches.",
    "trn.p1": "Como en Zermatt están prohibidos los coches de combustión, el último tramo del viaje se hace en tren. El tren lanzadera circula entre Täsch y Zermatt desde primera hora de la mañana hasta bien entrada la noche, aproximadamente cada 20 minutos, y cubre la distancia en unos 12 minutos.",
    "trn.h2a": "Billetes y andén",
    "trn.p2": "El andén está justo al lado del aparcamiento — sin calles que cruzar y con ascensores y rampas hasta las vías. Lo más cómodo es añadir los billetes de la lanzadera a tu reserva de parking; también puedes comprarlos en las máquinas del terminal o en una app ferroviaria.",
    "trn.callout": "Añade tus billetes del Zermatt Shuttle en el mismo formulario de la reserva de parking — o cómpralos más tarde en las máquinas del terminal.",
    "trn.h2b": "Equipaje y continuación",
    "trn.p3": "Hay carros para el equipaje en ambos andenes, y muchos hoteles de Zermatt envían un taxi eléctrico a recoger a sus huéspedes a la llegada. En temporada alta, cuando los trenes y los andenes están llenos, deja algo de margen.",
    "trn.f1k": "Línea",
    "trn.f1v": "Lanzadera Täsch ⇄ Zermatt",
    "trn.f2k": "Frecuencia",
    "trn.f2v": "≈ cada 20 min",
    "trn.f3k": "Trayecto",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Billetes",
    "trn.f4v": "Online o en el terminal",
    "red.h1": "Movilidad reducida y accesibilidad",
    "red.lead": "Aparcamiento accesible en el terminal y acceso sin escalones a la lanzadera.",
    "red.p1": "El Matterhorn Terminal está diseñado sin escalones. Las plazas accesibles están cerca de los ascensores, que te llevan directamente al andén de la lanzadera sin escaleras.",
    "red.h2a": "Aparcar cerca de los ascensores",
    "red.p2": "Reserva una plaza estándar online como de costumbre; si tienes tarjeta de estacionamiento para personas con discapacidad, al llegar aparca en una plaza accesible señalizada cerca de los ascensores. Gracias al reconocimiento de matrículas, no tienes que alcanzar ninguna máquina desde el coche.",
    "red.h2b": "Al tren y hacia Zermatt",
    "red.p3": "Ascensores y rampas conectan el aparcamiento con el andén, y los trenes lanzadera admiten sillas de ruedas. En Zermatt se pueden reservar taxis eléctricos para continuar hasta tu hotel. Lleva lo que necesites para un traslado sin complicaciones:",
    "red.li1": "Tu confirmación de aparcamiento (vinculada a tu matrícula)",
    "red.li2": "Una tarjeta de estacionamiento para personas con discapacidad válida para las plazas accesibles",
    "red.f1k": "Acceso",
    "red.f1v": "Sin escalones, ascensores al andén",
    "red.f2k": "Plazas",
    "red.f2v": "Plazas accesibles junto a los ascensores",
    "red.f3k": "Tren",
    "red.f3v": "Tren accesible en silla de ruedas",
    "red.f4k": "Llevar",
    "red.f4v": "Confirmación + tarjeta de estacionamiento",
