    "book.maxHeight": "A járművek maximális magassága: 2,30 méter.",
    "book.priceHint": "Válassza ki a dátumokat az ár megtekintéséhez.",
    "book.longStay": "Kedvezményes hosszú távú díj (8 naptól)",
    "book.holderNote": "A foglalás visszaigazolását erre az e-mail-címre küldjük.",
    "gh.title": "Parkolási információk",
    "gh.lead": "Minden tudnivaló a täschi Matterhorn Terminalban való parkolásról és az autómentes Zermattba jutásról – hogyan érkezzen, hogyan töltse fel elektromos autóját, és hogyan működik az ingavonat.",
    "gh.banner": "Zermatt autómentes. Minden autó megáll Täschben: parkoljon a Matterhorn Terminalban, és folytassa ingavonattal vagy taxival.",
    "gh.car.d": "Érkezzen Täschbe a völgyi úton, parkoljon a fedett terminálban, és szálljon fel a vonatra. Útvonal és magasságkorlát.",
    "gh.charging.d": "131 töltőállomás a terminálnál. Foglaljon töltővel felszerelt helyet, és töltsön, amíg Zermattban van.",
    "gh.train.d": "Az ingavonat körülbelül 12 perc alatt köti össze Täscht és Zermattot, nagyjából 20 percenként. A jegyeket a parkolással együtt lefoglalhatja, vagy megveheti a terminálnál.",
    "gh.reduced.d": "Akadálymentes helyek a liftek közelében, és lépcsőmentes hozzáférés az ingavonat peronjához.",
    "car.h1": "Érkezés autóval",
    "car.lead": "Hogyan jusson el a täschi Matterhorn Terminalhoz, és hol hagyja az autót Zermatthoz.",
    "car.p1": "Zermatt autómentes, így minden autós út a Matterhornhoz Täschben ér véget. A Rhône-völgyből a kantonúton haladjon felfelé Vispen, St. Niklauson és Randán át; a Matterhorn Terminal közvetlenül a täschi állomás mellett található, a völgyi út végén. Állítsa a navigációt a „Matterhorn Terminal Täsch” címre, és egyenesen a bejárathoz vezeti.",
    "car.h2a": "Parkolás a terminálnál",
    "car.p2": "A terminál egy fedett, többszintes parkolóház mintegy 2100 hellyel. Az online foglaláskor rögzül a rendszáma, így a sorompó érkezéskor automatikusan nyílik, és egyenesen egy helyhez hajthat – nincs megőrzendő papírjegy. Válassza a „Parkolás” lehetőséget normál helyhez, vagy a „Parkolás töltőállomással” lehetőséget, ha az autót tölteni kell.",
    "car.callout": "foglaljon online, mielőtt elindul. A sorompó felismeri a rendszámát, így be- és kihajtáskor sem kell a fizetőautomatához mennie.",
    "car.h2b": "A magasságkorlát",
    "car.p3": "A járművek maximális magassága 2,30 méter – ez elég a hagyományos autóknak, a kombiknak és a legtöbb tetőbox nélküli SUV-nak. A magasabb járművek, például a lakóautók, nem használhatják a fedett parkolóházat.",
    "car.h2c": "Az autótól Zermattig",
    "car.p4": "Az ingavonat peronja két perc sétára van a parkolóháztól. Az autómentes Zermattba tartó vonatok nagyjából 20 percenként indulnak, és körülbelül 12 percig tartanak; taxik és elektromos szállodai transzferek is felveszik az utasokat a terminálnál.",
    "car.f1k": "Parkoló",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Helyek",
    "car.f2v": "≈ 2100, fedett",
    "car.f3k": "Max. magasság",
    "car.f3v": "2,30 m",
    "car.f4k": "Zermattba",
    "car.f4v": "Ingavonat, ≈ 12 perc",
    "chg.h1": "Elektromos járművek és töltés",
    "chg.lead": "Elektromos autója töltése a zermatti látogatás alatt, és hogyan foglaljon töltőhelyet.",
    "chg.p1": "A Matterhorn Terminal az Alpok egyik legnagyobb töltőhelye, 131 töltőállomással a fedett parkolóházban. Az állomások legfeljebb 22 kW (AC) teljesítményt adnak fix kábellel és Type 2 csatlakozóval, így a legtöbb elektromos autó kényelmesen feltöltődik, amíg Ön fent van Zermattban.",
    "chg.h2a": "Töltőhely foglalása",
    "chg.p2": "Foglaláskor a normál parkolás helyett válassza a „Parkolás töltőállomással” lehetőséget. Így a teljes tartózkodás idejére töltő melletti helye lesz, és érkezéskor nem kell szabad töltőt keresnie.",
    "chg.callout": "a foglalási űrlap első lépésében válassza a „Parkolás töltőállomással” lehetőséget, így a kiválasztott napokra biztosan lesz töltője.",
    "chg.h2b": "Az energia kifizetése",
    "chg.p3": "A foglalás a töltővel felszerelt parkolóhelyre szól. A ténylegesen felhasznált áramot külön, a töltőnél QR-kóddal fizeti – hitelkártya, TWINT, Apple Pay és Google Pay egyaránt elfogadott –, így csak azért fizet, amit valóban felhasznált.",
    "chg.f1k": "Állomások",
    "chg.f1v": "131, a parkolóházban",
    "chg.f2k": "Teljesítmény",
    "chg.f2v": "max. 22 kW AC, Type 2",
    "chg.f3k": "Foglalás",
    "chg.f3v": "„Parkolás töltőállomással”",
    "chg.f4k": "Energia",
    "chg.f4v": "Fizetés a töltőnél QR-kóddal",
    "trn.h1": "Utazás Zermattba",
    "trn.lead": "Hogyan köti össze az ingavonat Täscht és az autómentes Zermattot.",
    "trn.p1": "Mivel Zermattban tilos a belső égésű motoros autók használata, az út utolsó szakaszát vonattal teszi meg. Az ingavonat kora reggeltől késő estig közlekedik Täsch és Zermatt között, nagyjából 20 percenként, és körülbelül 12 perc alatt ér célba.",
    "trn.h2a": "Jegyek és peron",
    "trn.p2": "A peron közvetlenül a parkolóház mellett van – nem kell utat keresztezni, a vágányokhoz liftek és rámpák vezetnek. A legegyszerűbb, ha az ingavonatjegyeket a parkolásfoglaláshoz adja; a terminál automatáiban vagy vasúti alkalmazásban is megveheti őket.",
    "trn.callout": "a Zermatt Shuttle jegyeket ugyanabban az űrlapban foglalhatja le, ahol a parkolást – vagy megveheti őket később a terminál automatáiban.",
    "trn.h2b": "Poggyász és továbbutazás",
    "trn.p3": "Mindkét peronon vannak poggyászkocsik, és sok zermatti szálloda elektromos taxit küld a vendégekért. Főszezonban, amikor zsúfoltak a vonatok és a peronok, számoljon egy kis ráhagyással.",
    "trn.f1k": "Vonal",
    "trn.f1v": "Täsch ⇄ Zermatt ingavonat",
    "trn.f2k": "Gyakoriság",
    "trn.f2v": "≈ 20 percenként",
    "trn.f3k": "Menetidő",
    "trn.f3v": "≈ 12 perc",
    "trn.f4k": "Jegyek",
    "trn.f4v": "Online vagy a terminálnál",
    "red.h1": "Csökkent mozgásképesség és akadálymentesség",
    "red.lead": "Akadálymentes parkolás a terminálnál és lépcsőmentes hozzáférés az ingavonathoz.",
    "red.p1": "A Matterhorn Terminal lépcsőmentesre tervezett. Az akadálymentes parkolóhelyek a liftek közelében találhatók, amelyek lépcsők nélkül visznek le közvetlenül az ingavonat peronjához.",
    "red.h2a": "Parkolás a liftek közelében",
    "red.p2": "Foglaljon normál helyet online a szokásos módon; ha mozgáskorlátozott parkolási igazolványa van, érkezéskor álljon egy kijelölt akadálymentes helyre a liftek közelében. A rendszámfelismerő sorompónak köszönhetően az autóból egyetlen automatát sem kell elérnie.",
    "red.h2b": "A vonatra és Zermattba",
    "red.p3": "Liftek és rámpák kötik össze a parkolóházat a peronnal, és az ingavonatok kerekesszéket is szállítanak. Zermattban elektromos taxi rendelhető a szállodához való továbbutazáshoz. Hozza magával, amire a zökkenőmentes átszálláshoz szüksége van:",
    "red.li1": "A parkolási visszaigazolása (a rendszámához kötve)",
    "red.li2": "Érvényes mozgáskorlátozott parkolókártya az akadálymentes helyekhez",
    "red.f1k": "Hozzáférés",
    "red.f1v": "Lépcsőmentes, liftek a peronhoz",
    "red.f2k": "Helyek",
    "red.f2v": "Akadálymentes helyek a lifteknél",
    "red.f3k": "Vonat",
    "red.f3v": "Kerekesszékkel használható ingavonat",
    "red.f4k": "Hozza magával",
    "red.f4v": "Visszaigazolás + parkolókártya",
