    "hero.title": "Zarezerwuj parking<br>w Täsch w drodze do Zermatt",
    "hero.subtitle": "Zarezerwuj miejsce w Matterhorn Terminal w Täsch i wjedź do wolnego od samochodów Zermatt pociągiem wahadłowym.",
    "info.title": "Zaparkuj i jedź do Zermatt",
    "info.guarantee": "Zermatt jest wolny od samochodów. Zostaw auto w Matterhorn Terminal w Täsch i wsiądź do pociągu wahadłowego – kursuje mniej więcej co 20 minut i dociera do Zermatt w około 12 minut.",
    "info.process": "Zarezerwuj online w kilka kliknięć. Po płatności otrzymasz e-mail z potwierdzeniem rezerwacji. Twoja tablica rejestracyjna zostaje zapisana dla szlabanu, więc dzięki rozpoznawaniu tablic po przyjeździe wjeżdżasz prosto do zadaszonego parkingu – bez biletu, który można zgubić.",
    "info.extra": "Terminal ma około 2100 zadaszonych miejsc i 131 stacji ładowania. Podczas rezerwacji wybierz „Parking ze stacją ładowania”, aby zarezerwować miejsce z ładowarką dla swojego samochodu elektrycznego.",
