    "red.p1": "Matterhorn Terminal zaprojektowano bezprogowo. Dostępne miejsca parkingowe znajdują się blisko wind, które zawożą Cię prosto na peron pociągu wahadłowego bez schodów.",
    "red.h2a": "Parkowanie blisko wind",
    "red.p2": "Zarezerwuj online zwykłe miejsce w standardowy sposób; jeśli masz kartę parkingową dla osób z niepełnosprawnością, po przyjeździe zaparkuj na oznaczonym miejscu dla osób z niepełnosprawnością przy windach. Dzięki rozpoznawaniu tablic nie musisz sięgać z auta do żadnego automatu.",
    "red.h2b": "Do pociągu i do Zermatt",
    "red.p3": "Windy i pochylnie łączą parking z peronem, a pociągi wahadłowe zabierają wózki inwalidzkie. W Zermatt można zamówić elektryczne taksówki, aby dojechać do hotelu. Zabierz to, czego potrzebujesz do sprawnego transferu:",
