    "info.guarantee": "Zermatt este o stațiune fără mașini. Lasă mașina la Matterhorn Terminal din Täsch și ia trenul navetă – circulă cam la fiecare 20 de minute și ajunge în Zermatt în aproximativ 12 minute.",
