    "book.holderNote": "Confirmarea rezervării va fi trimisă la această adresă de e-mail.",
    "gh.title": "Informații parcare",
    "gh.lead": "Tot ce trebuie să știi despre parcarea la Matterhorn Terminal din Täsch și despre drumul spre Zermatt fără mașini – cum ajungi, cum îți încarci mașina electrică și cum funcționează trenul navetă.",
    "gh.banner": "Zermatt este o stațiune fără mașini. Orice mașină se oprește în Täsch: parchează la Matterhorn Terminal și continuă cu trenul navetă sau cu taxiul.",
    "gh.car.d": "Ajungi în Täsch pe drumul din vale, parchezi în terminalul acoperit și urci în tren. Traseu și limita de înălțime.",
    "gh.charging.d": "131 de stații de încărcare la terminal. Rezervă un loc cu încărcător și încarcă mașina cât ești în Zermatt.",
    "gh.train.d": "Trenul navetă leagă Täsch de Zermatt în aproximativ 12 minute, cam la fiecare 20 de minute. Adaugă biletele la rezervare sau cumpără-le de la terminal.",
    "gh.reduced.d": "Locuri accesibile aproape de lifturi și acces fără trepte la peronul trenului navetă.",
    "car.h1": "Sosirea cu mașina",
    "car.lead": "Cum ajungi la Matterhorn Terminal din Täsch și unde lași mașina pentru Zermatt.",
    "car.p1": "Zermatt este o stațiune fără mașini, așa că orice drum cu mașina spre Matterhorn se termină în Täsch. Din valea Ronului urmezi drumul cantonal în urcare prin Visp, St. Niklaus și Randa; Matterhorn Terminal se află chiar lângă gara Täsch, la capătul drumului din vale. Setează navigația pe „Matterhorn Terminal Täsch” și te duce direct la intrare.",
    "car.h2a": "Parcarea la terminal",
    "car.p2": "Terminalul este o parcare acoperită cu mai multe niveluri, cu aproximativ 2.100 de locuri. La rezervarea online se salvează numărul tău, astfel încât bariera se deschide automat la sosire și mergi direct la un loc – fără tichet de hârtie de păstrat. Alege „Parcare” pentru un loc standard sau „Parcare cu stație de încărcare” dacă mașina trebuie încărcată.",
    "car.callout": "rezervă online înainte de plecare. Numărul tău este recunoscut la barieră, așa că eviți automatele de plată la intrare și la ieșire.",
    "car.h2b": "Limita de înălțime",
    "car.p3": "Înălțimea maximă este de 2,30 metri – suficient pentru autoturisme obișnuite, break-uri și majoritatea SUV-urilor fără cutie de plafon. Vehiculele mai înalte, cum ar fi autorulotele, nu pot folosi parcarea acoperită.",
    "car.h2c": "De la mașină la Zermatt",
    "car.p4": "Peronul trenului navetă este la două minute de mers pe jos de parcare. Trenurile spre Zermatt fără mașini pleacă cam la fiecare 20 de minute și durează aproximativ 12 minute; taxiurile și navetele electrice ale hotelurilor preiau de asemenea pasageri la terminal.",
    "car.f1k": "Parcare",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Locuri",
    "car.f2v": "≈ 2.100, acoperite",
    "car.f3k": "Înălțime max.",
    "car.f3v": "2,30 m",
    "car.f4k": "Spre Zermatt",
    "car.f4v": "Tren navetă, ≈ 12 min",
    "chg.h1": "Vehicule electrice și încărcare",
    "chg.lead": "Încărcarea mașinii electrice în timpul vizitei în Zermatt și cum rezervi un loc de încărcare.",
    "chg.p1": "Matterhorn Terminal este unul dintre cele mai mari puncte de încărcare din Alpi, cu 131 de stații integrate în parcarea acoperită. Stațiile oferă până la 22 kW (AC), cu cablu fix și conector Type 2, așa că majoritatea mașinilor electrice se încarcă liniștit cât timp ești în Zermatt.",
    "chg.h2a": "Rezervarea unui loc de încărcare",
    "chg.p2": "La rezervare, alege „Parcare cu stație de încărcare” în loc de parcarea standard. Astfel ai un loc lângă un încărcător pe toată durata șederii și nu trebuie să cauți un încărcător liber la sosire.",
    "chg.callout": "alege „Parcare cu stație de încărcare” la primul pas al formularului ca să ai încărcătorul garantat în datele tale.",
    "chg.h2b": "Plata energiei",
    "chg.p3": "Rezervarea ta acoperă locul de parcare și locul de încărcare. Energia consumată efectiv se facturează separat la stație prin cod QR – se acceptă card de credit, TWINT, Apple Pay și Google Pay – așa că plătești doar electricitatea pe care o folosești.",
    "chg.f1k": "Stații",
    "chg.f1v": "131, în parcare",
    "chg.f2k": "Putere",
    "chg.f2v": "până la 22 kW AC, Type 2",
    "chg.f3k": "Rezervă",
    "chg.f3v": "„Parcare cu stație de încărcare”",
    "chg.f4k": "Energie",
    "chg.f4v": "Plătită la stație prin QR",
    "trn.h1": "Cum ajungi în Zermatt",
    "trn.lead": "Cum leagă trenul navetă Täsch de Zermatt, stațiunea fără mașini.",
    "trn.p1": "Deoarece în Zermatt mașinile cu motor termic sunt interzise, ultima porțiune a drumului se face cu trenul. Trenul navetă circulă între Täsch și Zermatt de dimineața devreme până seara târziu, cam la fiecare 20 de minute, și parcurge distanța în aproximativ 12 minute.",
    "trn.h2a": "Bilete și peron",
    "trn.p2": "Peronul este chiar lângă parcare – fără străzi de traversat, cu lifturi și rampe până la linii. Cel mai simplu e să adaugi biletele de navetă la rezervarea parcării; le poți cumpăra și de la automatele din terminal sau dintr-o aplicație feroviară.",
    "trn.callout": "adaugă biletele Zermatt Shuttle în același formular în care rezervi parcarea – sau cumpără-le mai târziu de la automatele din terminal.",
    "trn.h2b": "Bagaje și continuarea călătoriei",
    "trn.p3": "Pe ambele peroane există cărucioare pentru bagaje, iar multe hoteluri din Zermatt trimit un taxi electric să-și ia oaspeții la sosire. În sezonul de vârf, când trenurile și peroanele sunt aglomerate, lasă-ți puțin timp de rezervă.",
    "trn.f1k": "Linie",
    "trn.f1v": "Naveta Täsch ⇄ Zermatt",
    "trn.f2k": "Frecvență",
    "trn.f2v": "≈ la fiecare 20 min",
