    "trn.f4v": "Online sau la terminal",
    "red.h1": "Mobilitate redusă și accesibilitate",
    "red.lead": "Parcare accesibilă la terminal și acces fără trepte la trenul navetă.",
    "red.p1": "Matterhorn Terminal este proiectat fără trepte. Locurile de parcare accesibile se află aproape de lifturi, care te duc direct la peronul trenului navetă, fără scări.",
    "red.h2a": "Parcarea aproape de lifturi",
    "red.p2": "Rezervă online un loc standard, ca de obicei; dacă ai un card de parcare pentru persoane cu dizabilități, la sosire parchează pe un loc accesibil marcat, lângă lifturi. Datorită recunoașterii plăcuțelor, nu trebuie să ajungi la niciun automat din mașină.",
    "red.h2b": "În tren și spre Zermatt",
