    "book.selectDates": "Vyberte prosím datum příjezdu a odjezdu.",
    "book.day": "den",
    "book.days": "dní",
    "book.maxHeight": "Maximální výška vozidel: 2,30 metru.",
    "book.priceHint": "Vyberte data a zobrazí se cena.",
    "book.longStay": "Uplatněna dlouhodobá sazba (od 8 dnů)",
    "book.holderNote": "Potvrzení rezervace vám pošleme na tuto e-mailovou adresu.",
    "gh.title": "Informace o parkování",
    "gh.lead": "Vše, co potřebujete vědět o parkování v Matterhorn Terminalu v Täsch a cestě do Zermattu, kde auta nejezdí – jak přijet, jak nabít elektromobil a jak funguje kyvadlový vlak.",
    "gh.banner": "Zermatt je bez aut. Každé auto zastaví v Täsch: zaparkujte v Matterhorn Terminalu a pokračujte kyvadlovým vlakem nebo taxíkem.",
    "gh.car.d": "Přijeďte do Täsch údolní silnicí, zaparkujte v krytém terminalu a nasedněte na vlak. Trasa a výškové omezení.",
    "gh.charging.d": "131 nabíjecích stanic u terminalu. Rezervujte si místo s nabíječkou a nabíjejte, zatímco jste v Zermattu.",
    "gh.train.d": "Kyvadlový vlak spojuje Täsch a Zermatt zhruba za 12 minut a jezdí přibližně každých 20 minut. Jízdenky přidáte k rezervaci parkování, nebo je koupíte v terminalu.",
    "gh.reduced.d": "Přístupná místa poblíž výtahů a bezbariérový přístup na nástupiště kyvadlového vlaku.",
    "car.h1": "Příjezd autem",
    "car.lead": "Jak dojet do Matterhorn Terminalu v Täsch a kam odstavit auto pro Zermatt.",
    "car.p1": "Zermatt je bez aut, takže každá cesta autem k Matterhornu končí v Täsch. Z údolí Rhôny pokračujete kantonální silnicí vzhůru přes Visp, St. Niklaus a Randu; Matterhorn Terminal stojí hned vedle nádraží Täsch na konci údolní silnice. Nastavte si navigaci na „Matterhorn Terminal Täsch“ a dovede vás rovnou ke vjezdu.",
    "car.h2a": "Parkování u terminalu",
    "car.p2": "Terminal je krytý vícepatrový parkovací dům s přibližně 2 100 místy. Při online rezervaci se uloží vaše značka, takže se závora při příjezdu otevře automaticky a vy zajedete rovnou na místo – žádný papírový lístek k uschování. Zvolte „Parkování“ pro běžné místo, nebo „Parkování s nabíjecí stanicí“, pokud se auto potřebuje nabít.",
    "car.callout": "rezervujte online, než vyrazíte. Závora rozpozná vaši značku, takže se při vjezdu i výjezdu obejdete bez platebních automatů.",
    "car.h2b": "Výškové omezení",
    "car.p3": "Maximální výška vozidla je 2,30 m – stačí pro běžná auta, kombi a většinu SUV bez střešního boxu. Vyšší vozidla, například obytné vozy, krytý parkovací dům využít nemohou.",
    "car.h2c": "Od auta do Zermattu",
    "car.p4": "Nástupiště kyvadlového vlaku je dvě minuty chůze od parkovacího domu. Vlaky do Zermattu jezdí zhruba každých 20 minut a cesta trvá asi 12 minut; u terminalu nabírají cestující také taxíky a elektrické hotelové shuttly.",
    "car.f1k": "Parkoviště",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Místa",
    "car.f2v": "≈ 2 100, krytá",
    "car.f3k": "Max. výška",
    "car.f3v": "2,30 m",
    "car.f4k": "Do Zermattu",
    "car.f4v": "Kyvadlový vlak, ≈ 12 min",
    "chg.h1": "Elektromobily a nabíjení",
    "chg.lead": "Nabíjení elektromobilu během návštěvy Zermattu a jak si rezervovat nabíjecí místo.",
    "chg.p1": "Matterhorn Terminal je jedním z největších nabíjecích míst v Alpách se 131 stanicemi zabudovanými do krytého parkovacího domu. Stanice dodávají až 22 kW (AC) s pevným kabelem a konektorem Type 2, takže většina elektromobilů se pohodlně nabije, zatímco jste nahoře v Zermattu.",
    "chg.h2a": "Rezervace nabíjecího místa",
    "chg.p2": "Při rezervaci zvolte „Parkování s nabíjecí stanicí“ místo běžného parkování. Tím si na celý pobyt rezervujete místo vedle nabíječky a nemusíte po příjezdu hledat volnou stanici.",
    "chg.callout": "zvolte „Parkování s nabíjecí stanicí“ hned v prvním kroku formuláře a nabíječku máte na své termíny jistou.",
    "chg.h2b": "Platba za energii",
    "chg.p3": "Vaše rezervace zahrnuje parkovací i nabíjecí místo. Skutečně odebraná energie se účtuje zvlášť u stanice pomocí QR kódu – přijímají se kreditní karta, TWINT, Apple Pay i Google Pay – takže platíte jen za elektřinu, kterou spotřebujete.",
    "chg.f1k": "Stanice",
    "chg.f1v": "131, v parkovacím domě",
    "chg.f2k": "Výkon",
    "chg.f2v": "až 22 kW AC, Type 2",
    "chg.f3k": "Rezervace",
    "chg.f3v": "„Parkování s nabíjecí stanicí“",
    "chg.f4k": "Energie",
    "chg.f4v": "U stanice přes QR kód",
    "trn.h1": "Cesta do Zermattu",
    "trn.lead": "Jak kyvadlový vlak spojuje Täsch se Zermattem, kde auta nejezdí.",
    "trn.p1": "Protože je v Zermattu provoz aut se spalovacím motorem zakázán, poslední úsek cesty pojedete vlakem. Kyvadlový vlak jezdí mezi Täsch a Zermattem od časného rána do pozdního večera, zhruba každých 20 minut, a trasu zvládne asi za 12 minut.",
    "trn.h2a": "Jízdenky a nástupiště",
    "trn.p2": "Nástupiště je hned vedle parkovacího domu – bez přecházení silnice, s výtahy a rampami ke kolejím. Nejjednodušší je přidat jízdenky na kyvadlový vlak rovnou k rezervaci parkování; koupit je můžete i v automatech v terminalu nebo v železniční aplikaci.",
    "trn.callout": "jízdenky na Zermatt Shuttle přidejte ve stejném formuláři, ve kterém rezervujete parkování – nebo si je kupte později v automatech v terminalu.",
    "trn.h2b": "Zavazadla a další cesta",
    "trn.p3": "Na obou nástupištích jsou vozíky na zavazadla a mnoho hotelů posílá elektrický taxík, který hosty po příjezdu do Zermattu vyzvedne. V hlavní sezoně, kdy jsou vlaky i nástupiště plné, si nechte trochu časové rezervy.",
    "trn.f1k": "Linka",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Interval",
    "trn.f2v": "≈ každých 20 min",
    "trn.f3k": "Jízda",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Jízdenky",
    "trn.f4v": "Online nebo v terminalu",
    "red.h1": "Omezená pohyblivost a přístupnost",
    "red.lead": "Přístupné parkování u terminalu a bezbariérový přístup ke kyvadlovému vlaku.",
    "red.p1": "Matterhorn Terminal je řešen bezbariérově. Přístupná parkovací místa jsou poblíž výtahů, které vás bez schodů dovezou přímo na nástupiště kyvadlového vlaku.",
    "red.h2a": "Parkování poblíž výtahů",
    "red.p2": "Rezervujte si běžné místo online obvyklým způsobem; máte-li průkaz pro osoby se zdravotním postižením, po příjezdu zaparkujte na vyhrazeném stání u výtahů. Díky rozpoznávání značek nemusíte z auta dosahovat na žádný automat.",
    "red.h2b": "Do vlaku a do Zermattu",
    "red.p3": "Výtahy a rampy spojují parkovací dům s nástupištěm a kyvadlové vlaky berou invalidní vozíky. V Zermattu si lze objednat elektrické taxíky pro cestu k hotelu. Vezměte si, co potřebujete pro plynulý přesun:",
    "red.li1": "Potvrzení parkování (vázané na vaši značku)",
    "red.li2": "Platný průkaz pro osoby se zdravotním postižením pro přístupná stání",
    "red.f1k": "Přístup",
    "red.f1v": "Bezbariérově, výtahy na nástupiště",
    "red.f2k": "Místa",
    "red.f2v": "Přístupná stání u výtahů",
    "red.f3k": "Vlak",
    "red.f3v": "Vlak přístupný pro vozíčkáře",
    "red.f4k": "Vezměte",
    "red.f4v": "Potvrzení + průkaz ZTP",
