    "hero.title": "Reserveer je parkeerplaats<br>in Täsch voor Zermatt",
    "hero.subtitle": "Reserveer je plek bij de Matterhorn Terminal in Täsch en reis met de pendeltrein het autovrije Zermatt in.",
    "info.title": "Park & Ride naar Zermatt",
    "info.guarantee": "Zermatt is autovrij. Laat je auto achter bij de Matterhorn Terminal in Täsch en neem de pendeltrein – hij rijdt ongeveer elke 20 minuten en bereikt Zermatt in zo'n 12 minuten.",
    "info.process": "Boek online in een paar klikken. Na betaling ontvang je een bevestigingsmail. Je kenteken wordt geregistreerd, zodat de slagboom dankzij kentekenherkenning vanzelf opengaat en je bij aankomst direct de overdekte garage in rijdt – geen parkeerkaartje om kwijt te raken.",
    "info.extra": "De terminal heeft ongeveer 2.100 overdekte plaatsen en 131 laadstations. Kies bij het boeken ‘Parkeren met laadstation’ als je een plek met laadpaal voor je elektrische auto wilt.",
    "adv.title": "Voordelen",
