    "book.selectDates": "Kies je aankomst- en vertrekdatum.",
    "book.day": "dag",
    "book.days": "dagen",
    "book.maxHeight": "Maximale voertuighoogte: 2,30 meter.",
    "book.priceHint": "Kies je data om de prijs te zien.",
    "book.longStay": "Tarief voor langparkeren toegepast (vanaf 8 dagen)",
    "book.holderNote": "De bevestiging van je boeking wordt naar dit e-mailadres gestuurd.",
    "gh.title": "Parkeerinformatie",
    "gh.lead": "Alles wat je moet weten om te parkeren bij de Matterhorn Terminal in Täsch en het autovrije Zermatt te bereiken – hoe je er komt, je elektrische auto opladen en hoe de pendeltrein werkt.",
    "gh.banner": "Zermatt is autovrij. Elke auto stopt in Täsch: parkeer bij de Matterhorn Terminal en reis verder met de pendeltrein of taxi.",
    "gh.car.d": "Rijd via de dalweg naar Täsch, parkeer in de overdekte terminal en stap op de trein. Route en hoogtebeperking.",
    "gh.charging.d": "131 laadstations bij de terminal. Reserveer een plek met laadpaal en laad op terwijl je in Zermatt bent.",
    "gh.train.d": "De pendeltrein verbindt Täsch en Zermatt in zo'n 12 minuten, ongeveer elke 20 minuten. Boek je tickets meteen bij je parkeerplaats of koop ze bij de terminal.",
    "gh.reduced.d": "Toegankelijke plaatsen dicht bij de liften en drempelvrije toegang tot het perron van de pendeltrein.",
    "car.h1": "Aankomst met de auto",
    "car.lead": "Hoe je naar de Matterhorn Terminal in Täsch rijdt en waar je de auto laat voor Zermatt.",
    "car.p1": "Zermatt is autovrij, dus elke autorit naar de Matterhorn eindigt in Täsch. Vanuit het Rhônedal volg je de kantonnale weg omhoog via Visp, St. Niklaus en Randa; de Matterhorn Terminal ligt pal naast station Täsch, aan het einde van de dalweg. Stel je navigatie in op ‘Matterhorn Terminal Täsch’ en die brengt je rechtstreeks naar de ingang.",
    "car.h2a": "Parkeren bij de terminal",
    "car.p2": "De terminal is een overdekte parkeergarage met meerdere verdiepingen en ongeveer 2.100 plaatsen. Bij het online boeken wordt je kenteken opgeslagen, zodat de slagboom bij aankomst automatisch opengaat en je direct naar een plek rijdt – geen papieren kaartje om te bewaren. Kies ‘Parkeren’ voor een gewone plek of ‘Parkeren met laadstation’ als je auto moet opladen.",
    "car.callout": "boek online voordat je vertrekt. Je kenteken wordt bij de slagboom herkend, zodat je bij in- en uitrijden de betaalautomaten overslaat.",
    "car.h2b": "De hoogtebeperking",
    "car.p3": "De maximale voertuighoogte is 2,30 meter: genoeg voor gewone auto's, stationwagens en de meeste SUV's zonder dakkoffer. Hogere voertuigen, zoals campers, kunnen de overdekte garage niet gebruiken.",
    "car.h2c": "Van de auto naar Zermatt",
    "car.p4": "Het perron van de pendeltrein ligt op twee minuten lopen van de garage. Treinen naar het autovrije Zermatt rijden ongeveer elke 20 minuten en duren ongeveer 12 minuten; taxi's en elektrische hotelshuttles pikken ook op bij de terminal.",
    "car.f1k": "Parkeergarage",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Plaatsen",
    "car.f2v": "≈ 2.100, overdekt",
    "car.f3k": "Max. hoogte",
    "car.f3v": "2,30 m",
    "car.f4k": "Naar Zermatt",
    "car.f4v": "Pendeltrein, ≈ 12 min",
    "chg.h1": "Elektrische voertuigen & laden",
    "chg.lead": "Je elektrische auto opladen tijdens je bezoek aan Zermatt en hoe je een laadplek reserveert.",
    "chg.p1": "De Matterhorn Terminal is een van de grootste laadlocaties in de Alpen, met 131 laadstations ingebouwd in de overdekte parkeergarage. De stations leveren tot 22 kW (AC) met een vaste kabel en Type 2-stekker, zodat de meeste elektrische auto's comfortabel laden terwijl jij boven in Zermatt bent.",
    "chg.h2a": "Een laadplek reserveren",
    "chg.p2": "Kies bij het boeken ‘Parkeren met laadstation’ in plaats van gewoon parkeren. Zo heb je voor je hele verblijf een plek naast een laadpaal en hoef je bij aankomst niet naar een vrije laadpaal te zoeken.",
    "chg.callout": "kies ‘Parkeren met laadstation’ in de eerste stap van het boekingsformulier, dan heb je gegarandeerd een laadpaal op je data.",
    "chg.h2b": "De energie betalen",
    "chg.p3": "Je reservering dekt de parkeerplaats en de laadplek. De energie die je daadwerkelijk afneemt, wordt apart bij het station afgerekend via QR-code – creditcard, TWINT, Apple Pay en Google Pay worden geaccepteerd – zo betaal je alleen de stroom die je gebruikt.",
    "chg.f1k": "Laadpunten",
    "chg.f1v": "131, in de garage",
    "chg.f2k": "Vermogen",
    "chg.f2v": "tot 22 kW AC, Type 2",
    "chg.f3k": "Boeken",
    "chg.f3v": "‘Parkeren met laadstation’",
    "chg.f4k": "Energie",
    "chg.f4v": "Afrekenen bij de laadpaal via QR-code",
    "trn.h1": "Naar Zermatt reizen",
    "trn.lead": "Hoe de pendeltrein Täsch en het autovrije Zermatt verbindt.",
    "trn.p1": "Omdat auto's met een verbrandingsmotor in Zermatt verboden zijn, leg je het laatste stuk per trein af. De pendeltrein rijdt tussen Täsch en Zermatt van 's ochtends vroeg tot laat in de avond, ongeveer elke 20 minuten, en doet over de rit zo'n 12 minuten.",
    "trn.h2a": "Tickets & perron",
    "trn.p2": "Het perron ligt pal naast de parkeergarage – geen straat oversteken, met liften en hellingbanen naar de sporen. Het makkelijkst is om de pendeltickets meteen aan je parkeerboeking toe te voegen; je kunt ze ook kopen bij de automaten in de terminal of in een spoor-app.",
    "trn.callout": "voeg je Zermatt Shuttle-tickets toe in hetzelfde formulier als je parkeerplaats – of koop ze later bij de automaten in de terminal.",
    "trn.h2b": "Bagage & doorreis",
    "trn.p3": "Op beide perrons staan bagagekarren, en veel hotels in Zermatt sturen een elektrische taxi om gasten bij aankomst op te halen. Houd in het hoogseizoen, als treinen en perrons druk zijn, wat extra tijd aan.",
    "trn.f1k": "Lijn",
    "trn.f1v": "Pendel Täsch ⇄ Zermatt",
    "trn.f2k": "Frequentie",
    "trn.f2v": "≈ elke 20 min",
    "trn.f3k": "Reistijd",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Tickets",
    "trn.f4v": "Online of bij de terminal",
    "red.h1": "Beperkte mobiliteit & toegankelijkheid",
    "red.lead": "Toegankelijk parkeren bij de terminal en drempelvrije toegang tot de pendeltrein.",
    "red.p1": "De Matterhorn Terminal is drempelvrij ontworpen. Toegankelijke parkeerplaatsen liggen dicht bij de liften, die je zonder trappen rechtstreeks naar het perron van de pendeltrein brengen.",
    "red.h2a": "Parkeren dicht bij de liften",
    "red.p2": "Reserveer online op de gebruikelijke manier een gewone plek; heb je een gehandicaptenparkeerkaart, parkeer dan bij aankomst op een gemarkeerde gehandicaptenplek bij de liften. Dankzij de kentekenherkenning hoef je vanuit de auto geen automaat te bereiken.",
    "red.h2b": "De trein in en naar Zermatt",
    "red.p3": "Liften en hellingbanen verbinden de parkeergarage met het perron, en de pendeltreinen nemen rolstoelen mee. In Zermatt zijn elektrische taxi's te boeken om door te reizen naar je hotel. Neem mee wat je nodig hebt voor een soepele overstap:",
    "red.li1": "Je parkeerbevestiging (gekoppeld aan je kenteken)",
    "red.li2": "Een geldige gehandicaptenparkeerkaart voor de toegankelijke plekken",
