    "hero.title": "Rezervirajte parkirno mesto<br>v Täschu za obisk Zermatta",
    "hero.subtitle": "Rezervirajte mesto na Matterhorn Terminalu v Täschu in se z vlakom pripeljite v Zermatt brez avtomobilov.",
    "info.title": "Parkirajte in nadaljujte v Zermatt",
    "info.guarantee": "Zermatt je brez avtomobilov. Pustite avto na Matterhorn Terminalu v Täschu in se odpeljite z vlakom – vozi približno vsakih 20 minut in do Zermatta pride v približno 12 minutah.",
    "info.process": "Rezervirajte na spletu v nekaj klikih. Po plačilu prejmete potrditveno e-pošto z rezervacijo. Vaša registrska tablica se shrani za zapornico, tako da s prepoznavanjem tablic ob prihodu zapeljete naravnost v pokrito garažo – brez listka, ki bi ga lahko izgubili.",
    "info.extra": "Terminal ima približno 2.100 pokritih mest in 131 polnilnih postaj. Pri rezervaciji izberite »Parkiranje s polnilno postajo« in rezervirajte polnilno mesto za svoj električni avto.",
