    "book.holderNote": "Potrdilo o rezervaciji bomo poslali na ta e-poštni naslov.",
    "gh.title": "Informacije o parkiranju",
    "gh.lead": "Vse, kar morate vedeti o parkiranju na Matterhorn Terminalu v Täschu in poti v Zermatt brez avtomobilov – kako priti, kako napolniti električni avto in kako deluje vlak.",
    "gh.banner": "Zermatt je brez avtomobilov. Vsak avto se ustavi v Täschu: parkirajte na Matterhorn Terminalu in nadaljujte z vlakom ali taksijem.",
    "gh.car.d": "Pripeljite se v Täsch po dolinski cesti, parkirajte v pokritem terminalu in se vkrcajte na vlak. Pot in omejitev višine.",
    "gh.charging.d": "131 polnilnih postaj na terminalu. Rezervirajte mesto s polnilnico in polnite, medtem ko ste v Zermattu.",
    "gh.train.d": "Vlak povezuje Täsch in Zermatt v približno 12 minutah in vozi približno vsakih 20 minut. Vozovnice dodate k rezervaciji parkiranja ali jih kupite na terminalu.",
    "gh.reduced.d": "Dostopna mesta blizu dvigal in dostop brez stopnic do perona vlaka.",
    "car.h1": "Prihod z avtomobilom",
    "car.lead": "Kako se pripeljati do Matterhorn Terminala v Täschu in kje pustiti avto za Zermatt.",
    "car.p1": "Zermatt je brez avtomobilov, zato se vsaka vožnja k Matterhornu konča v Täschu. Iz doline Rone nadaljujete po kantonski cesti navzgor skozi Visp, St. Niklaus in Rando; Matterhorn Terminal stoji tik ob postaji Täsch na koncu dolinske ceste. Navigacijo nastavite na »Matterhorn Terminal Täsch« in vas popelje naravnost do vhoda.",
    "car.h2a": "Parkiranje na terminalu",
    "car.p2": "Terminal je pokrita večnadstropna garaža z približno 2.100 mesti. Ob spletni rezervaciji se shrani vaša tablica, tako da se zapornica ob prihodu samodejno odpre in se odpeljete naravnost do mesta – brez papirnatega listka za shranjevanje. Izberite »Parkiranje« za običajno mesto ali »Parkiranje s polnilno postajo«, če se mora avto polniti.",
    "car.callout": "rezervirajte na spletu, preden se odpravite na pot. Zapornica prepozna vašo tablico, zato se ob vhodu in izhodu izognete plačilnim avtomatom.",
    "car.h2b": "Omejitev višine",
    "car.p3": "Največja višina vozila je 2,30 m – dovolj za običajne avtomobile, karavane in večino terencev brez strešnega kovčka. Višja vozila, na primer avtodomi, ne morejo v pokrito garažo.",
    "car.h2c": "Od avta do Zermatta",
    "car.p4": "Peron vlaka je dve minuti hoje od garaže. Vlaki v Zermatt brez avtomobilov vozijo približno vsakih 20 minut in trajajo približno 12 minut; taksiji in električni hotelski prevozi prav tako pobirajo potnike na terminalu.",
    "car.f1k": "Parkirišče",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Mesta",
    "car.f2v": "≈ 2.100, pokrita",
    "car.f3k": "Najv. višina",
    "car.f3v": "2,30 m",
    "car.f4k": "V Zermatt",
    "car.f4v": "Vlak, ≈ 12 min",
    "chg.h1": "Električna vozila in polnjenje",
    "chg.lead": "Polnjenje električnega avta med obiskom Zermatta in kako rezervirati polnilno mesto.",
    "chg.p1": "Matterhorn Terminal je eno največjih polnilnih mest v Alpah s 131 postajami, vgrajenimi v pokrito garažo. Postaje zagotavljajo do 22 kW (AC) s pritrjenim kablom in vtičem Type 2, tako da se večina električnih avtomobilov udobno napolni, medtem ko ste zgoraj v Zermattu.",
    "chg.h2a": "Rezervacija polnilnega mesta",
    "chg.p2": "Ob rezervaciji izberite »Parkiranje s polnilno postajo« namesto običajnega parkiranja. Tako imate za ves čas bivanja mesto ob polnilnici in vam ob prihodu ni treba iskati proste polnilnice.",
    "chg.callout": "v prvem koraku obrazca izberite »Parkiranje s polnilno postajo« in polnilnica bo za vaše datume zagotovljena.",
    "chg.h2b": "Plačilo energije",
    "chg.p3": "Vaša rezervacija zajema parkirno in polnilno mesto. Dejansko porabljena energija se obračuna posebej pri postaji prek kode QR – sprejeti so kreditna kartica, TWINT, Apple Pay in Google Pay – tako plačate le elektriko, ki jo porabite.",
    "chg.f1k": "Postaje",
    "chg.f1v": "131, v garaži",
    "chg.f2k": "Moč",
    "chg.f2v": "do 22 kW AC, Type 2",
    "chg.f3k": "Rezervacija",
    "chg.f3v": "»Parkiranje s polnilno postajo«",
    "chg.f4k": "Energija",
    "chg.f4v": "Plačilo pri postaji s kodo QR",
    "trn.h1": "Pot v Zermatt",
    "trn.lead": "Kako vlak povezuje Täsch in Zermatt brez avtomobilov.",
    "trn.p1": "Ker so v Zermattu avtomobili z motorjem na notranje izgorevanje prepovedani, zadnji del poti opravite z vlakom. Vlak vozi med Täschem in Zermattom od zgodnjega jutra do poznega večera, približno vsakih 20 minut, razdaljo pa premaga v približno 12 minutah.",
    "trn.h2a": "Vozovnice in peron",
    "trn.p2": "Peron je tik ob garaži – brez prečkanja ceste, z dvigali in klančinami do tirov. Najpreprosteje je, da vozovnice za vlak dodate k rezervaciji parkiranja; kupite jih lahko tudi na avtomatih v terminalu ali v železniški aplikaciji.",
    "trn.callout": "vozovnice za Zermatt Shuttle dodajte v istem obrazcu, v katerem rezervirate parkiranje – ali jih kupite pozneje na avtomatih v terminalu.",
    "trn.h2b": "Prtljaga in nadaljevanje poti",
    "trn.p3": "Na obeh peronih so vozički za prtljago, mnogi hoteli v Zermattu pa pošljejo električni taksi, ki goste pričaka ob prihodu. V glavni sezoni, ko so vlaki in peroni polni, si pustite nekaj časovne rezerve.",
    "trn.f1k": "Proga",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Pogostost",
    "trn.f2v": "≈ vsakih 20 min",
    "trn.f3k": "Vožnja",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Vozovnice",
    "trn.f4v": "Na spletu ali na terminalu",
    "red.h1": "Zmanjšana mobilnost in dostopnost",
    "red.lead": "Dostopno parkiranje na terminalu in dostop brez stopnic do vlaka.",
    "red.p1": "Matterhorn Terminal je zasnovan brez stopnic. Dostopna parkirna mesta so blizu dvigal, ki vas brez stopnic pripeljejo naravnost do perona vlaka.",
    "red.h2a": "Parkiranje blizu dvigal",
    "red.p2": "Običajno mesto rezervirajte na spletu kot vedno; če imate parkirno karto za invalide, ob prihodu parkirajte na označenem mestu za invalide ob dvigalih. Zaradi prepoznavanja tablic vam iz avta ni treba seči do nobenega avtomata.",
    "red.h2b": "Na vlak in v Zermatt",
    "red.p3": "Dvigala in klančine povezujejo garažo s peronom, vlaki pa sprejmejo invalidske vozičke. V Zermattu je mogoče naročiti električne taksije za nadaljevanje do hotela. Prinesite, kar potrebujete za nemoten prestop:",
    "red.li1": "Potrdilo o parkiranju (vezano na vašo tablico)",
    "red.li2": "Veljavno parkirno karto za invalide za dostopna mesta",
