    "info.title": "Estacione e siga para Zermatt",
    "info.guarantee": "Zermatt é uma vila sem carros. Deixe o carro no Matterhorn Terminal em Täsch e apanhe o comboio de ligação — parte a cada 20 minutos, aproximadamente, e chega a Zermatt em cerca de 12 minutos.",
    "info.process": "Reserve online em poucos cliques. Após o pagamento, receberá um e-mail de confirmação. A sua matrícula fica registada: graças ao reconhecimento de matrículas, a cancela abre-se e entra diretamente no parque coberto — sem bilhete para perder.",
    "info.extra": "O terminal tem cerca de 2100 lugares cobertos e 131 estações de carregamento. Ao reservar, escolha «Estacionamento com estação de carregamento» para garantir um lugar com carregador para o seu carro elétrico.",
