    "gh.title": "Info de estacionamento",
    "gh.lead": "Tudo o que precisa de saber para estacionar no Matterhorn Terminal em Täsch e chegar a Zermatt sem carros — como chegar, carregar o seu carro elétrico e como funciona o comboio de ligação.",
    "gh.banner": "Zermatt é livre de carros. Todos os carros param em Täsch: estacione no Matterhorn Terminal e continue de comboio de ligação ou táxi.",
    "gh.car.d": "Chegue a Täsch pela estrada do vale, estacione no terminal coberto e apanhe o comboio. Percurso e limite de altura.",
    "gh.charging.d": "131 estações de carregamento no terminal. Reserve um lugar com carregador e carregue o carro enquanto está em Zermatt.",
    "gh.train.d": "O comboio de ligação une Täsch e Zermatt em cerca de 12 minutos, a cada 20 minutos, aproximadamente. Adicione os bilhetes à reserva ou compre-os no terminal.",
    "gh.reduced.d": "Lugares acessíveis perto dos elevadores e acesso sem degraus à plataforma do comboio de ligação.",
    "car.h1": "Chegar de carro",
    "car.lead": "Como chegar ao Matterhorn Terminal em Täsch e onde deixar o carro para Zermatt.",
    "car.p1": "Zermatt é uma vila sem carros, por isso todas as viagens de carro até ao Matterhorn terminam em Täsch. A partir do vale do Ródano, siga a estrada cantonal a subir por Visp, St. Niklaus e Randa; o Matterhorn Terminal fica mesmo ao lado da estação de Täsch, no fim da estrada do vale. Introduza «Matterhorn Terminal Täsch» no GPS e será levado diretamente à entrada.",
    "car.h2a": "Estacionar no terminal",
    "car.p2": "O terminal é um parque coberto de vários pisos com cerca de 2100 lugares. Ao reservar online, a sua matrícula fica guardada, por isso a cancela abre-se automaticamente à chegada e segue diretamente para um lugar — sem bilhete de papel para guardar. Escolha «Estacionamento» para um lugar normal ou «Estacionamento com estação de carregamento» se precisar de carregar o carro.",
    "car.callout": "Reserve online antes de partir. A sua matrícula é reconhecida na cancela, o que lhe poupa as máquinas de pagamento à entrada e à saída.",
    "car.h2b": "O limite de altura",
    "car.p3": "A altura máxima é de 2,30 metros — suficiente para carros normais, carrinhas e a maioria dos SUV sem caixa de tejadilho. Veículos mais altos, como autocaravanas, não podem utilizar o parque coberto.",
    "car.h2c": "Do carro a Zermatt",
    "car.p4": "A plataforma do comboio de ligação fica a dois minutos a pé do parque. Os comboios para Zermatt sem carros partem cerca de cada 20 minutos e demoram cerca de 12 minutos; táxis e transferes elétricos de hotéis também recolhem no terminal.",
    "car.f1k": "Parque",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Lugares",
    "car.f2v": "≈ 2100, cobertos",
    "car.f3k": "Altura máx.",
    "car.f3v": "2,30 m",
    "car.f4k": "Para Zermatt",
    "car.f4v": "Comboio de ligação, ≈ 12 min",
    "chg.h1": "Veículos elétricos e carregamento",
    "chg.lead": "Carregar o seu carro elétrico durante a visita a Zermatt e como reservar um lugar de carregamento.",
    "chg.p1": "O Matterhorn Terminal é um dos maiores locais de carregamento dos Alpes, com 131 estações integradas no parque coberto. As estações fornecem até 22 kW (AC) com cabo fixo e ficha Type 2, por isso a maioria dos carros elétricos carrega comodamente enquanto está em Zermatt.",
    "chg.h2a": "Reservar um lugar de carregamento",
    "chg.p2": "Ao reservar, escolha «Estacionamento com estação de carregamento» em vez do estacionamento normal. Assim, fica com um lugar junto a um carregador durante toda a estadia, sem ter de procurar um carregador livre à chegada.",
    "chg.callout": "Escolha «Estacionamento com estação de carregamento» no primeiro passo do formulário para garantir um carregador nas suas datas.",
    "chg.h2b": "Pagar a energia",
    "chg.p3": "A sua reserva cobre o lugar de estacionamento e o lugar de carregamento. A energia efetivamente consumida é cobrada em separado na estação por código QR — são aceites cartão de crédito, TWINT, Apple Pay e Google Pay — por isso paga apenas a eletricidade que usa.",
    "chg.f1k": "Estações",
    "chg.f1v": "131, no parque",
    "chg.f2k": "Potência",
    "chg.f2v": "até 22 kW AC, Type 2",
    "chg.f3k": "Reserva",
    "chg.f3v": "«Estacionamento com estação de carregamento»",
    "chg.f4k": "Energia",
    "chg.f4v": "Paga na estação com código QR",
    "trn.h1": "Como chegar a Zermatt",
    "trn.lead": "Como o comboio de ligação une Täsch e Zermatt sem carros.",
    "trn.p1": "Como os carros com motor de combustão são proibidos em Zermatt, a última etapa da viagem faz-se de comboio. O comboio de ligação circula entre Täsch e Zermatt desde manhã cedo até à noite, a cada 20 minutos, aproximadamente, e percorre a distância em cerca de 12 minutos.",
    "trn.h2a": "Bilhetes e plataforma",
    "trn.p2": "A plataforma fica mesmo ao lado do parque — sem ruas para atravessar e com elevadores e rampas até às linhas. O mais prático é adicionar os bilhetes do comboio de ligação à sua reserva de estacionamento; também os pode comprar nas máquinas do terminal ou numa app ferroviária.",
    "trn.callout": "Adicione os bilhetes do Zermatt Shuttle no mesmo formulário da reserva de estacionamento — ou compre-os mais tarde nas máquinas do terminal.",
    "trn.h2b": "Bagagem e continuação",
    "trn.p3": "Há carrinhos de bagagem em ambas as plataformas, e muitos hotéis de Zermatt enviam um táxi elétrico para ir buscar os hóspedes à chegada. Na época alta, quando comboios e plataformas estão cheios, conte com alguma margem de tempo.",
    "trn.f1k": "Linha",
    "trn.f1v": "Ligação Täsch ⇄ Zermatt",
    "trn.f2k": "Frequência",
    "trn.f2v": "≈ cada 20 min",
    "trn.f3k": "Viagem",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Bilhetes",
    "trn.f4v": "Online ou no terminal",
    "red.h1": "Mobilidade reduzida e acessibilidade",
    "red.lead": "Estacionamento acessível no terminal e acesso sem degraus ao comboio de ligação.",
    "red.p1": "O Matterhorn Terminal foi concebido sem degraus. Os lugares acessíveis situam-se perto dos elevadores, que o levam diretamente à plataforma do comboio de ligação sem escadas.",
    "red.h2a": "Estacionar perto dos elevadores",
    "red.p2": "Reserve online um lugar normal como habitualmente; se tiver um dístico de estacionamento para pessoas com deficiência, à chegada estacione num lugar acessível assinalado perto dos elevadores. Graças à cancela com reconhecimento de matrícula, não precisa de alcançar nenhuma máquina a partir do carro.",
    "red.h2b": "Para o comboio e até Zermatt",
    "red.p3": "Elevadores e rampas ligam o parque à plataforma, e os comboios de ligação aceitam cadeiras de rodas. Em Zermatt podem reservar-se táxis elétricos para seguir até ao hotel. Leve o que precisa para uma transferência sem problemas:",
    "red.li1": "A sua confirmação de estacionamento (associada à sua matrícula)",
    "red.li2": "Um dístico de estacionamento para pessoas com deficiência válido para os lugares acessíveis",
    "red.f1k": "Acesso",
    "red.f1v": "Sem degraus, elevadores para a plataforma",
    "red.f2k": "Lugares",
    "red.f2v": "Lugares acessíveis junto aos elevadores",
    "red.f3k": "Comboio",
    "red.f3v": "Ligação acessível a cadeiras de rodas",
    "red.f4k": "Levar",
    "red.f4v": "Confirmação + dístico de estacionamento",
