    "hero.title": "Rezervirajte parking<br>u Täschu za Zermatt",
    "hero.subtitle": "Rezervirajte mjesto na Matterhorn Terminalu u Täschu i vlakom se dovezite u Zermatt bez automobila.",
    "info.title": "Parkirajte i nastavite u Zermatt",
    "info.guarantee": "Zermatt je bez automobila. Ostavite auto na Matterhorn Terminalu u Täschu i sjednite na vlak – polazi otprilike svakih 20 minuta i do Zermatta stiže za oko 12 minuta.",
    "info.process": "Rezervirajte online u nekoliko klikova. Nakon plaćanja primit ćete e-poštu s potvrdom. Vaša se registarska oznaka registrira, pa se rampa zahvaljujući prepoznavanju tablica otvara sama i pri dolasku ulazite ravno u natkrivenu garažu – bez karte koju biste mogli izgubiti.",
    "info.extra": "Terminal ima oko 2.100 natkrivenih mjesta i 131 stanicu za punjenje. Pri rezervaciji odaberite »Parking sa stanicom za punjenje« kako biste rezervirali mjesto za punjenje svog električnog automobila.",
