    "book.maxHeight": "Maksimalna visina vozila: 2,30 metra.",
    "book.priceHint": "Odaberite datume za prikaz cijene.",
    "book.longStay": "Cijena za dulje parkiranje (od 8 dana)",
    "book.holderNote": "Potvrdu rezervacije poslat ćemo na ovu e-adresu.",
    "gh.title": "Informacije o parkingu",
    "gh.lead": "Sve što trebate znati o parkiranju na Matterhorn Terminalu u Täschu i dolasku u Zermatt bez automobila – kako doći, kako napuniti električni automobil i kako radi vlak.",
    "gh.banner": "Zermatt je bez automobila. Svaki automobil staje u Täschu: parkirajte na Matterhorn Terminalu i nastavite vlakom ili taksijem.",
    "gh.car.d": "Dođite u Täsch dolinskom cestom, parkirajte u natkrivenom terminalu i sjednite na vlak. Ruta i ograničenje visine.",
    "gh.charging.d": "131 stanica za punjenje na terminalu. Rezervirajte mjesto s punjačem i punite automobil dok ste u Zermattu.",
    "gh.train.d": "Vlak povezuje Täsch i Zermatt za oko 12 minuta i vozi otprilike svakih 20 minuta. Karte dodajte uz rezervaciju parkinga ili ih kupite na terminalu.",
    "gh.reduced.d": "Pristupačna mjesta blizu dizala i pristup bez stepenica do perona vlaka.",
    "car.h1": "Dolazak automobilom",
    "car.lead": "Kako doći do Matterhorn Terminala u Täschu i gdje ostaviti auto za Zermatt.",
    "car.p1": "Zermatt je bez automobila, pa svako putovanje autom prema Matterhornu završava u Täschu. Iz doline Rone nastavljate kantonalnom cestom uzbrdo kroz Visp, St. Niklaus i Randu; Matterhorn Terminal nalazi se odmah uz kolodvor Täsch na kraju dolinske ceste. Postavite navigaciju na »Matterhorn Terminal Täsch« i odvest će vas ravno do ulaza.",
    "car.h2a": "Parkiranje na terminalu",
    "car.p2": "Terminal je natkrivena višeetažna garaža s oko 2.100 mjesta. Pri online rezervaciji sprema se vaša pločica, pa se rampa pri dolasku automatski otvara i idete ravno do mjesta – bez papirnate karte za čuvanje. Odaberite »Parking« za obično mjesto ili »Parking sa stanicom za punjenje« ako se auto treba puniti.",
    "car.callout": "rezervirajte online prije polaska. Rampa prepoznaje vašu pločicu pa pri ulazu i izlazu ne morate do naplatnih automata.",
    "car.h2b": "Ograničenje visine",
    "car.p3": "Najveća dopuštena visina vozila je 2,30 m – dovoljno za obične automobile, karavane i većinu SUV-ova bez krovne kutije. Viša vozila, poput kampera, ne mogu u natkrivenu garažu.",
    "car.h2c": "Od auta do Zermatta",
    "car.p4": "Peron vlaka je dvije minute hoda od garaže. Vlakovi za Zermatt bez automobila polaze otprilike svakih 20 minuta i traju oko 12 minuta; taksiji i električni hotelski prijevozi također preuzimaju putnike na terminalu.",
    "car.f1k": "Parkiralište",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Mjesta",
    "car.f2v": "≈ 2.100, natkrivena",
    "car.f3k": "Maks. visina",
    "car.f3v": "2,30 m",
    "car.f4k": "Do Zermatta",
    "car.f4v": "Vlak, ≈ 12 min",
    "chg.h1": "Električna vozila i punjenje",
    "chg.lead": "Punjenje električnog automobila tijekom posjeta Zermattu i kako rezervirati mjesto za punjenje.",
    "chg.p1": "Matterhorn Terminal jedno je od najvećih mjesta za punjenje u Alpama, sa 131 stanicom ugrađenom u natkrivenu garažu. Stanice pružaju do 22 kW (AC) s fiksnim kabelom i utikačem Type 2, pa se većina električnih automobila udobno napuni dok ste gore u Zermattu.",
    "chg.h2a": "Rezervacija mjesta za punjenje",
    "chg.p2": "Pri rezervaciji odaberite »Parking sa stanicom za punjenje« umjesto običnog parkinga. Tako za cijeli boravak imate mjesto uz punjač i pri dolasku ne morate tražiti slobodan punjač.",
    "chg.callout": "u prvom koraku obrasca odaberite »Parking sa stanicom za punjenje« i punjač će vam za vaše datume biti osiguran.",
    "chg.h2b": "Plaćanje energije",
    "chg.p3": "Vaša rezervacija pokriva parkirno mjesto i mjesto za punjenje. Stvarno preuzeta energija naplaćuje se zasebno na stanici putem QR koda – prihvaćaju se kreditna kartica, TWINT, Apple Pay i Google Pay – pa plaćate samo struju koju potrošite.",
    "chg.f1k": "Stanice",
    "chg.f1v": "131, u garaži",
    "chg.f2k": "Snaga",
    "chg.f2v": "do 22 kW AC, Type 2",
    "chg.f3k": "Rezervacija",
    "chg.f3v": "»Parking sa stanicom za punjenje«",
    "chg.f4k": "Energija",
    "chg.f4v": "Plaća se na stanici putem QR-a",
    "trn.h1": "Dolazak u Zermatt",
    "trn.lead": "Kako vlak povezuje Täsch i Zermatt bez automobila.",
    "trn.p1": "Budući da su u Zermattu automobili s motorom s unutarnjim izgaranjem zabranjeni, posljednju dionicu putujete vlakom. Vlak vozi između Täscha i Zermatta od ranog jutra do kasne večeri, otprilike svakih 20 minuta, a udaljenost prelazi za oko 12 minuta.",
    "trn.h2a": "Karte i peron",
    "trn.p2": "Peron je odmah uz garažu – bez prelaska ceste, s dizalima i rampama do kolosijeka. Najjednostavnije je karte za vlak dodati uz rezervaciju parkinga; možete ih kupiti i na automatima u terminalu ili u željezničkoj aplikaciji.",
    "trn.callout": "karte za Zermatt Shuttle dodajte u istom obrascu u kojem rezervirate parking – ili ih kupite kasnije na automatima u terminalu.",
    "trn.h2b": "Prtljaga i nastavak putovanja",
    "trn.p3": "Na oba perona postoje kolica za prtljagu, a mnogi hoteli u Zermattu šalju električni taksi koji goste dočeka po dolasku. U jeku sezone, kad su vlakovi i peroni puni, ostavite malo vremena u rezervi.",
    "trn.f1k": "Linija",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Učestalost",
    "trn.f2v": "≈ svakih 20 min",
    "trn.f3k": "Vožnja",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Karte",
    "trn.f4v": "Online ili na terminalu",
    "red.h1": "Smanjena pokretljivost i pristupačnost",
    "red.lead": "Pristupačno parkiranje na terminalu i pristup bez stepenica do vlaka.",
    "red.p1": "Matterhorn Terminal osmišljen je bez stepenica. Pristupačna parkirna mjesta nalaze se blizu dizala koja vas bez stepenica dovode ravno do perona vlaka.",
    "red.h2a": "Parkiranje blizu dizala",
    "red.p2": "Obično mjesto rezervirajte online kao i inače; ako imate parkirnu kartu za osobe s invaliditetom, pri dolasku parkirajte na označenom mjestu za osobe s invaliditetom uz dizala. Zahvaljujući prepoznavanju pločica iz auta ne morate posezati ni za kakvim automatom.",
    "red.h2b": "U vlak i u Zermatt",
    "red.p3": "Dizala i rampe povezuju garažu s peronom, a vlakovi primaju invalidska kolica. U Zermattu se mogu naručiti električni taksiji do hotela. Ponesite sve što vam treba za jednostavan presjed:",
    "red.li1": "Potvrdu parkinga (vezanu uz vašu pločicu)",
    "red.li2": "Važeću parkirnu kartu za osobe s invaliditetom za pristupačna mjesta",
    "red.f1k": "Pristup",
    "red.f1v": "Bez stepenica, dizala do perona",
    "red.f2k": "Mjesta",
    "red.f2v": "Pristupačna mjesta uz dizala",
