    "hero.title": "Rezervujte si parkovanie<br>v Täsch, bráne do Zermattu",
    "hero.subtitle": "Rezervujte si miesto v Matterhorn Termináli v Täsch a do Zermattu, kde autá nejazdia, sa zvezte kyvadlovým vlakom.",
    "info.title": "Zaparkujte a pokračujte do Zermattu",
    "info.guarantee": "Zermatt je bez áut. Nechajte auto v Matterhorn Termináli v Täsch a nastúpte na kyvadlový vlak – premáva približne každých 20 minút a do Zermattu príde asi za 12 minút.",
    "info.process": "Rezervujte online na pár kliknutí. Po platbe dostanete potvrdzovací e-mail s rezerváciou. Vaša evidenčná značka sa uloží pre závoru, takže vďaka rozpoznávaniu značiek pri príchode vojdete rovno do krytého parkovacieho domu – žiadny lístok, ktorý by ste mohli stratiť.",
    "info.extra": "Terminál má približne 2 100 krytých miest a 131 nabíjacích staníc. Pri rezervácii zvoľte „Parkovanie s nabíjacou stanicou“ a rezervujte si nabíjacie miesto pre svoj elektromobil.",
    "adv.title": "Výhody",
    "adv.subtitle": "Všetko, čo získate, keď rezervujete u nás",
    "adv.covered.t": "Krytý parkovací dom",
