    "book.holderNote": "Potvrdenie rezervácie vám pošleme na túto e-mailovú adresu.",
    "gh.title": "Informácie o parkovaní",
    "gh.lead": "Všetko, čo potrebujete vedieť o parkovaní v Matterhorn Termináli v Täsch a ceste do Zermattu, kde autá nejazdia – ako prísť, ako nabiť elektromobil a ako funguje kyvadlový vlak.",
    "gh.banner": "Zermatt je bez áut. Každé auto zastaví v Täsch: zaparkujte v Matterhorn Termináli a pokračujte kyvadlovým vlakom alebo taxíkom.",
    "gh.car.d": "Príďte do Täsch údolnou cestou, zaparkujte v krytom termináli a nastúpte na vlak. Trasa a výškové obmedzenie.",
    "gh.charging.d": "131 nabíjacích staníc pri termináli. Rezervujte si miesto s nabíjačkou a nabíjajte, kým ste v Zermatte.",
    "gh.train.d": "Kyvadlový vlak spája Täsch a Zermatt za približne 12 minút a premáva zhruba každých 20 minút. Lístky pridáte k rezervácii parkovania alebo si ich kúpite v termináli.",
    "gh.reduced.d": "Prístupné miesta blízko výťahov a bezbariérový prístup na nástupište kyvadlového vlaku.",
    "car.h1": "Príchod autom",
    "car.lead": "Ako sa dostať do Matterhorn Terminálu v Täsch a kde nechať auto pre Zermatt.",
    "car.p1": "Zermatt je bez áut, takže každá cesta autom k Matterhornu končí v Täsch. Z údolia Rhôny pokračujete kantonálnou cestou nahor cez Visp, St. Niklaus a Randu; Matterhorn Terminál stojí hneď vedľa stanice Täsch na konci údolnej cesty. Nastavte si navigáciu na „Matterhorn Terminal Täsch“ a dovedie vás rovno k vjazdu.",
    "car.h2a": "Parkovanie pri termináli",
    "car.p2": "Terminál je krytý viacpodlažný parkovací dom s približne 2 100 miestami. Pri online rezervácii sa uloží vaša značka, takže sa závora pri príchode otvorí automaticky a zájdete rovno na miesto – žiadny papierový lístok na uschovanie. Zvoľte „Parkovanie“ pre bežné miesto alebo „Parkovanie s nabíjacou stanicou“, ak sa auto potrebuje nabiť.",
    "car.callout": "rezervujte online skôr, než vyrazíte. Závora rozpozná vašu značku, takže sa pri vjazde aj výjazde zaobídete bez platobných automatov.",
    "car.h2b": "Výškové obmedzenie",
    "car.p3": "Maximálna výška vozidla je 2,30 m – stačí pre bežné autá, kombi a väčšinu SUV bez strešného boxu. Vyššie vozidlá, napríklad obytné autá, krytý parkovací dom využiť nemôžu.",
    "car.h2c": "Od auta do Zermattu",
    "car.p4": "Nástupište kyvadlového vlaku je dve minúty chôdze od parkovacieho domu. Vlaky do Zermattu premávajú zhruba každých 20 minút a cesta trvá asi 12 minút; pri termináli naberajú cestujúcich aj taxíky a elektrické hotelové shuttle.",
    "car.f1k": "Parkovisko",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Miesta",
    "car.f2v": "≈ 2 100, kryté",
    "car.f3k": "Max. výška",
    "car.f3v": "2,30 m",
    "car.f4k": "Do Zermattu",
    "car.f4v": "Kyvadlový vlak, ≈ 12 min",
    "chg.h1": "Elektromobily a nabíjanie",
    "chg.lead": "Nabíjanie elektromobilu počas návštevy Zermattu a ako si rezervovať nabíjacie miesto.",
    "chg.p1": "Matterhorn Terminál je jedným z najväčších nabíjacích miest v Alpách so 131 stanicami zabudovanými do krytého parkovacieho domu. Stanice dodávajú až 22 kW (AC) s pevným káblom a konektorom Type 2, takže väčšina elektromobilov sa pohodlne nabije, kým ste hore v Zermatte.",
    "chg.h2a": "Rezervácia nabíjacieho miesta",
    "chg.p2": "Pri rezervácii zvoľte „Parkovanie s nabíjacou stanicou“ namiesto bežného parkovania. Tým si na celý pobyt rezervujete miesto vedľa nabíjačky a nemusíte po príchode hľadať voľnú stanicu.",
    "chg.callout": "zvoľte „Parkovanie s nabíjacou stanicou“ hneď v prvom kroku formulára a nabíjačku máte na svoje termíny istú.",
    "chg.h2b": "Platba za energiu",
    "chg.p3": "Vaša rezervácia zahŕňa parkovacie aj nabíjacie miesto. Skutočne odobratá energia sa účtuje zvlášť pri stanici pomocou QR kódu – prijímajú sa kreditná karta, TWINT, Apple Pay aj Google Pay – takže platíte len za elektrinu, ktorú spotrebujete.",
    "chg.f1k": "Stanice",
    "chg.f1v": "131, v parkovacom dome",
    "chg.f2k": "Výkon",
    "chg.f2v": "až 22 kW AC, Type 2",
    "chg.f3k": "Rezervácia",
    "chg.f3v": "„Parkovanie s nabíjacou stanicou“",
    "chg.f4k": "Energia",
    "chg.f4v": "Pri stanici cez QR kód",
    "trn.h1": "Cesta do Zermattu",
    "trn.lead": "Ako kyvadlový vlak spája Täsch so Zermattom, kde autá nejazdia.",
    "trn.p1": "Keďže je v Zermatte premávka áut so spaľovacím motorom zakázaná, posledný úsek cesty pôjdete vlakom. Kyvadlový vlak premáva medzi Täsch a Zermattom od skorého rána do neskorého večera, zhruba každých 20 minút, a trasu zvládne asi za 12 minút.",
    "trn.h2a": "Lístky a nástupište",
    "trn.p2": "Nástupište je hneď vedľa parkovacieho domu – bez prechádzania cesty, s výťahmi a rampami ku koľajam. Najjednoduchšie je pridať lístky na kyvadlový vlak rovno k rezervácii parkovania; kúpiť si ich môžete aj v automatoch v termináli alebo v železničnej aplikácii.",
    "trn.callout": "lístky na Zermatt Shuttle pridajte v tom istom formulári, v ktorom rezervujete parkovanie – alebo si ich kúpte neskôr v automatoch v termináli.",
    "trn.h2b": "Batožina a ďalšia cesta",
    "trn.p3": "Na oboch nástupištiach sú vozíky na batožinu a mnohé hotely posielajú elektrický taxík, ktorý hostí po príchode do Zermattu vyzdvihne. V hlavnej sezóne, keď sú vlaky aj nástupištia plné, si nechajte trochu časovej rezervy.",
    "trn.f1k": "Linka",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Interval",
    "trn.f2v": "≈ každých 20 min",
    "trn.f3k": "Jazda",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Lístky",
    "trn.f4v": "Online alebo v termináli",
    "red.h1": "Obmedzená pohyblivosť a prístupnosť",
    "red.lead": "Prístupné parkovanie pri termináli a bezbariérový prístup ku kyvadlovému vlaku.",
    "red.p1": "Matterhorn Terminál je riešený bezbariérovo. Prístupné parkovacie miesta sú blízko výťahov, ktoré vás bez schodov dovezú priamo na nástupište kyvadlového vlaku.",
    "red.h2a": "Parkovanie blízko výťahov",
    "red.p2": "Rezervujte si bežné miesto online zvyčajným spôsobom; ak máte preukaz pre osoby so zdravotným postihnutím, po príchode zaparkujte na vyhradenom státí pri výťahoch. Vďaka rozpoznávaniu značiek nemusíte z auta dosahovať na žiadny automat.",
    "red.h2b": "Do vlaku a do Zermattu",
    "red.p3": "Výťahy a rampy spájajú parkovací dom s nástupišťom a kyvadlové vlaky berú invalidné vozíky. V Zermatte si možno objednať elektrické taxíky na cestu k hotelu. Vezmite si, čo potrebujete pre plynulý presun:",
    "red.li1": "Potvrdenie parkovania (viazané na vašu značku)",
    "red.li2": "Platný preukaz pre osoby so zdravotným postihnutím pre prístupné státia",
    "red.f1k": "Prístup",
    "red.f1v": "Bezbariérovo, výťahy na nástupište",
    "red.f2k": "Miesta",
    "red.f2v": "Prístupné státia pri výťahoch",
    "red.f3k": "Vlak",
    "red.f3v": "Vlak prístupný pre vozíčkarov",
    "red.f4k": "Vezmite",
    "red.f4v": "Potvrdenie + preukaz ZŤP",
