    "hero.title": "Rezervišite parking<br>u Täschu za Zermatt",
    "hero.subtitle": "Rezervišite mesto na Matterhorn Terminalu u Täschu i vozom se dovezite u Zermatt bez automobila.",
    "info.title": "Parkirajte i nastavite u Zermatt",
    "info.guarantee": "Zermatt je bez automobila. Ostavite auto na Matterhorn Terminalu u Täschu i sednite na voz – polazi otprilike svakih 20 minuta i do Zermatta stiže za oko 12 minuta.",
    "info.process": "Rezervišite onlajn u nekoliko klikova. Nakon plaćanja dobićete imejl sa potvrdom. Vaša registarska tablica se registruje, pa se zahvaljujući prepoznavanju tablica rampa otvara sama i pri dolasku ulazite pravo u natkrivenu garažu – bez karte koju biste mogli da izgubite.",
    "info.extra": "Terminal ima oko 2.100 natkrivenih mesta i 131 stanicu za punjenje. Pri rezervaciji izaberite »Parking sa stanicom za punjenje« da biste rezervisali mesto za punjenje svog električnog automobila.",
