    "hero.title": "Забронюйте паркування<br>у Täsch для Zermatt",
    "hero.subtitle": "Забронюйте місце в Matterhorn Terminal у Täsch і доїжджайте потягом-шатлом до Zermatt, де немає автомобілів.",
    "info.title": "Припаркуйтеся та їдьте до Zermatt",
    "info.guarantee": "Zermatt вільний від автомобілів. Залиште авто в Matterhorn Terminal у Täsch і сядьте на потяг — він ходить приблизно кожні 20 хвилин і дістається Zermatt приблизно за 12 хвилин.",
    "info.process": "Бронюйте онлайн за кілька кліків. Після оплати ви отримаєте лист-підтвердження з бронюванням. Ваш номерний знак зберігається для шлагбаума, тож завдяки розпізнаванню номерів ви після прибуття в'їжджаєте прямо до критого паркінгу — без квитка, який можна загубити.",
    "info.extra": "Термінал має близько 2 100 критих місць і 131 зарядну станцію. Під час бронювання оберіть «Паркування із зарядною станцією», щоб зарезервувати місце із зарядкою для електромобіля.",
