    "info.guarantee": "Zermatt закрыт для автомобилей. Оставьте машину на терминале Matterhorn Terminal в Täsch и пересядьте на поезд — он ходит примерно каждые 20 минут и доезжает до Zermatt примерно за 12 минут.",
    "info.process": "Бронируйте онлайн в несколько кликов. После оплаты вы получите письмо с подтверждением. Номер вашего автомобиля заносится в систему: шлагбаум распознает его и пропустит вас прямо в крытый паркинг — никаких парковочных талонов, которые можно потерять.",
