    "book.ticketDiscount": "Льготный тариф (50%) — для владельцев Half Fare Card и Swiss Half Fare Card, детей от 6 до 15 лет и собак выше 30 см в холке.",
    "gh.title": "Информация о парковке",
    "gh.lead": "Всё, что нужно знать о парковке на терминале Matterhorn Terminal в Täsch и о поездке в свободный от машин Zermatt — как добраться, как зарядить электромобиль и как работает поезд-шаттл.",
    "gh.banner": "Zermatt закрыт для автомобилей. Каждая машина останавливается в Täsch: паркуйтесь на терминале Matterhorn Terminal и продолжайте путь на поезде или такси.",
    "gh.car.d": "Доезжайте до Täsch по долине, оставляйте машину в крытом паркинге терминала и садитесь на поезд. Маршрут и ограничение по высоте.",
    "gh.charging.d": "131 зарядная станция на терминале. Забронируйте место с зарядной станцией и заряжайте автомобиль, пока вы в Zermatt.",
    "gh.train.d": "Поезд-шаттл связывает Täsch и Zermatt примерно за 12 минут и ходит примерно каждые 20 минут. Добавьте билеты прямо к бронированию парковки или купите их на терминале.",
    "gh.reduced.d": "Доступные места рядом с лифтами и безбарьерный доступ к платформе поезда-шаттла.",
    "car.h1": "Прибытие на автомобиле",
    "car.lead": "Как доехать до терминала Matterhorn Terminal в Täsch и где оставить машину для поездки в Zermatt.",
    "car.p1": "Zermatt закрыт для автомобилей, поэтому любая поездка на машине к Маттерхорну заканчивается в Täsch. Из долины Роны дорога идёт по кантональной трассе через Visp, St. Niklaus и Randa; терминал Matterhorn Terminal находится прямо у станции Täsch, в конце дороги вдоль долины. Задайте в навигаторе «Matterhorn Terminal Täsch» — и он приведёт вас прямо ко въезду.",
    "car.h2a": "Парковка на терминале",
    "car.p2": "Терминал — это крытый многоуровневый паркинг примерно на 2 100 мест. При онлайн-бронировании сохраняется номер вашего автомобиля, поэтому по прибытии шлагбаум откроется автоматически и вы сразу проедете к месту — бумажный билет не нужен. Выберите «Паркинг» для обычного места или «Паркинг с зарядной станцией», если автомобиль нужно зарядить.",
    "car.callout": "бронируйте онлайн заранее. Шлагбаум распознаёт ваш номер, поэтому на въезде и выезде не придётся платить в автоматах.",
    "car.h2b": "Ограничение по высоте",
    "car.p3": "Максимальная высота автомобиля — 2,30 м: этого достаточно для обычных легковых машин, универсалов и большинства внедорожников без бокса на крыше. Более высокие автомобили, например автодома, в крытый паркинг не заедут.",
    "car.h2c": "От машины до Zermatt",
    "car.p4": "Платформа поезда-шаттла находится в двух минутах ходьбы от паркинга. Поезда до свободного от машин Zermatt ходят примерно каждые 20 минут и в пути около 12 минут; такси и отельные электрошаттлы также забирают пассажиров прямо с терминала.",
    "car.f1k": "Паркинг",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Места",
    "car.f2v": "≈ 2100, крытые",
    "car.f3k": "Макс. высота",
    "car.f3v": "2,30 м",
    "car.f4k": "До Zermatt",
    "car.f4v": "Поезд, ≈ 12 мин",
    "chg.h1": "Электромобили и зарядка",
    "chg.lead": "Зарядка электромобиля во время поездки в Zermatt и как забронировать место с зарядкой.",
    "chg.p1": "Matterhorn Terminal — один из крупнейших пунктов зарядки в Альпах: 131 зарядная станция встроена прямо в крытый паркинг. Станции выдают до 22 кВт (AC) через фиксированный кабель с разъёмом Type 2, поэтому большинство электромобилей спокойно заряжаются, пока вы наверху, в Zermatt.",
    "chg.h2a": "Бронирование места с зарядкой",
    "chg.p2": "При бронировании выберите «Паркинг с зарядной станцией» вместо обычной парковки. Так за вами на весь срок пребывания закрепляется место рядом с зарядной станцией — не придётся искать свободную колонку по приезде.",
    "chg.callout": "выберите «Паркинг с зарядной станцией» на первом шаге формы — и зарядка на ваши даты будет гарантирована.",
    "chg.h2b": "Оплата электроэнергии",
    "chg.p3": "Бронирование включает место с зарядной станцией. Фактически израсходованная электроэнергия оплачивается отдельно прямо на станции по QR-коду — принимаются банковские карты, TWINT, Apple Pay и Google Pay, — так что вы платите только за то, что реально использовали.",
    "chg.f1k": "Станции",
