    "chg.f2v": "До 22 кВт AC, Type 2",
    "chg.f3k": "Бронирование",
    "chg.f3v": "«Паркинг с зарядной станцией»",
    "chg.f4k": "Энергия",
    "chg.f4v": "Оплата на станции по QR-коду",
    "trn.h1": "Как добраться до Zermatt",
    "trn.lead": "Как поезд-шаттл связывает Täsch и свободный от машин Zermatt.",
    "trn.p1": "Поскольку в Zermatt запрещены автомобили с двигателем внутреннего сгорания, последний участок пути нужно проехать по железной дороге. Поезд-шаттл курсирует между Täsch и Zermatt с раннего утра до позднего вечера примерно каждые 20 минут и преодолевает расстояние примерно за 12 минут.",
    "trn.h2a": "Билеты и платформа",
    "trn.p2": "Платформа находится прямо рядом с паркингом — не нужно переходить дорогу, к путям ведут лифты и пандусы. Проще всего добавить билеты на шаттл прямо к бронированию парковки онлайн; также их можно купить в автоматах на терминале или в приложении железной дороги.",
    "trn.callout": "добавьте билеты на Zermatt Shuttle в той же форме, где бронируете парковку, — или купите их позже в автоматах на терминале.",
    "trn.h2b": "Багаж и дальнейший путь",
    "trn.p3": "На обеих платформах есть тележки для багажа, а многие отели Zermatt присылают электротакси встречать гостей со стороны Zermatt. В высокий сезон закладывайте немного больше времени — поезда и платформы бывают загружены.",
    "trn.f1k": "Линия",
    "trn.f1v": "Шаттл Täsch ⇄ Zermatt",
    "trn.f2k": "Частота",
    "trn.f2v": "≈ каждые 20 мин",
    "trn.f3k": "В пути",
    "trn.f3v": "≈ 12 мин",
    "trn.f4k": "Билеты",
    "trn.f4v": "Онлайн или на терминале",
    "red.h1": "Гостям с ограниченной мобильностью",
    "red.lead": "Доступная парковка на терминале и безбарьерный доступ к поезду-шаттлу.",
    "red.p1": "Matterhorn Terminal спроектирован без ступеней. Доступные парковочные места расположены рядом с лифтами, которые без лестниц довезут вас прямо до платформы поезда-шаттла.",
    "red.h2a": "Парковка рядом с лифтами",
    "red.p2": "Бронируйте стандартное место онлайн, как обычно; если у вас есть парковочное удостоверение для людей с инвалидностью, по приезде паркуйтесь на отмеченном месте для инвалидов у лифтов. Благодаря распознаванию номеров не нужно тянуться из машины к автомату.",
    "red.h2b": "К поезду и в Zermatt",
