    "gh.title": "Parkeringsinfo",
    "gh.lead": "Alt hvad du behøver at vide om parkering ved Matterhorn Terminal i Täsch og om at nå det bilfrie Zermatt – hvordan du ankommer, oplader din elbil og hvordan shuttletoget fungerer.",
    "gh.banner": "Zermatt er bilfrit. Alle biler stopper i Täsch: parkér ved Matterhorn Terminal, og fortsæt med shuttletog eller taxa.",
    "gh.car.d": "Kør til Täsch ad dalvejen, parkér i den overdækkede terminal, og hop på toget. Rute og højdegrænse.",
    "gh.charging.d": "131 ladestationer ved terminalen. Reservér en plads med lader, og oplad, mens du er i Zermatt.",
    "gh.train.d": "Shuttletoget forbinder Täsch og Zermatt på cirka 12 minutter, omtrent hvert 20. minut. Book billetterne sammen med parkeringen, eller køb dem ved terminalen.",
    "gh.reduced.d": "Tilgængelige pladser tæt på elevatorerne og trinfri adgang til shuttletogets perron.",
    "car.h1": "Ankomst med bil",
    "car.lead": "Sådan kører du til Matterhorn Terminal i Täsch, og hvor du efterlader bilen til Zermatt.",
    "car.p1": "Zermatt er bilfrit, så enhver biltur til Matterhorn ender i Täsch. Fra Rhône-dalen følger du kantonvejen op gennem Visp, St. Niklaus og Randa; Matterhorn Terminal ligger lige ved siden af Täsch station for enden af dalvejen. Sæt navigationen til »Matterhorn Terminal Täsch«, så føres du direkte til indkørslen.",
    "car.h2a": "Parkering ved terminalen",
    "car.p2": "Terminalen er et overdækket parkeringshus i flere etager med omkring 2.100 pladser. Ved onlinebooking gemmes din nummerplade, så bommen åbner automatisk ved ankomst, og du kører direkte til en plads – ingen papirbillet at gemme. Vælg »Parkering« for en almindelig plads eller »Parkering med ladestation«, hvis din bil skal oplades.",
    "car.callout": "Book online, inden du kører. Din nummerplade genkendes ved bommen, så du slipper for betalingsautomaterne både ind og ud.",
    "car.h2b": "Højdegrænsen",
    "car.p3": "Den maksimale højde er 2,30 meter – nok til almindelige biler, stationcars og de fleste SUV'er uden tagboks. Højere køretøjer, fx autocampere, kan ikke bruge det overdækkede parkeringshus.",
    "car.h2c": "Fra bilen til Zermatt",
    "car.p4": "Shuttletogets perron er to minutters gang fra parkeringshuset. Tog til det bilfrie Zermatt kører omtrent hvert 20. minut og tager cirka 12 minutter; taxaer og elektriske hotelshuttles henter også ved terminalen.",
    "car.f1k": "Parkering",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Pladser",
    "car.f2v": "≈ 2.100, overdækket",
    "car.f3k": "Maks. højde",
    "car.f3v": "2,30 m",
    "car.f4k": "Til Zermatt",
    "car.f4v": "Shuttletog, ≈ 12 min",
    "chg.h1": "Elbiler og opladning",
    "chg.lead": "Opladning af din elbil under besøget i Zermatt, og hvordan du reserverer en ladeplads.",
    "chg.p1": "Matterhorn Terminal er et af de største ladesteder i Alperne med 131 ladestationer indbygget i det overdækkede parkeringshus. Stationerne leverer op til 22 kW (AC) med fast kabel og Type 2-stik, så de fleste elbiler oplader bekvemt, mens du er oppe i Zermatt.",
    "chg.h2a": "Reservation af en ladeplads",
    "chg.p2": "Ved bookingen vælger du »Parkering med ladestation« i stedet for almindelig parkering. Så har du en plads ved siden af en lader under hele opholdet og skal ikke lede efter en ledig lader ved ankomst.",
    "chg.callout": "Vælg »Parkering med ladestation« i første trin af bookingformularen for at være sikker på en lader på dine datoer.",
    "chg.h2b": "Betaling for energien",
    "chg.p3": "Din reservation dækker parkeringspladsen og ladepladsen. Den energi, du faktisk bruger, afregnes separat ved stationen via QR-kode – kreditkort, TWINT, Apple Pay og Google Pay accepteres – så du betaler kun for den strøm, du bruger.",
    "chg.f1k": "Stationer",
    "chg.f1v": "131, i p-huset",
    "chg.f2k": "Effekt",
    "chg.f2v": "op til 22 kW AC, Type 2",
    "chg.f3k": "Booking",
    "chg.f3v": "»Parkering med ladestation«",
    "chg.f4k": "Energi",
    "chg.f4v": "Betales ved stationen via QR",
    "trn.h1": "Sådan når du Zermatt",
    "trn.lead": "Hvordan shuttletoget forbinder Täsch og det bilfrie Zermatt.",
    "trn.p1": "Da biler med forbrændingsmotor er forbudt i Zermatt, foregår den sidste del af rejsen med tog. Shuttletoget kører mellem Täsch og Zermatt fra tidlig morgen til sent om aftenen, omtrent hvert 20. minut, og tilbagelægger strækningen på cirka 12 minutter.",
    "trn.h2a": "Billetter og perron",
    "trn.p2": "Perronen ligger lige ved siden af parkeringshuset – ingen vej at krydse, og der er elevatorer og ramper ned til sporene. Nemmest er det at tilføje shuttlebilletterne til din parkeringsbooking; du kan også købe dem i automaterne i terminalen eller i en togapp.",
    "trn.callout": "Tilføj dine Zermatt Shuttle-billetter i samme formular, som du booker parkeringen i – eller køb dem senere i automaterne i terminalen.",
    "trn.h2b": "Bagage og videre rejse",
    "trn.p3": "Der er bagagevogne på begge perroner, og mange hoteller i Zermatt sender en eltaxa for at hente gæsterne ved ankomsten. Læg lidt ekstra tid ind i højsæsonen, når tog og perroner er fyldte.",
    "trn.f1k": "Linje",
    "trn.f1v": "Täsch ⇄ Zermatt shuttle",
    "trn.f2k": "Frekvens",
    "trn.f2v": "≈ hvert 20. min",
    "trn.f3k": "Rejsetid",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Billetter",
    "trn.f4v": "Online eller ved terminalen",
    "red.h1": "Nedsat mobilitet og tilgængelighed",
    "red.lead": "Tilgængelig parkering ved terminalen og trinfri adgang til shuttletoget.",
    "red.p1": "Matterhorn Terminal er designet trinfrit. Tilgængelige parkeringspladser ligger tæt på elevatorerne, der fører dig direkte ned til shuttletogets perron uden trapper.",
    "red.h2a": "Parkering tæt på elevatorerne",
    "red.p2": "Reservér en almindelig plads online på sædvanlig vis; har du et handicapparkeringskort, så parkér ved ankomst på en markeret handicapplads nær elevatorerne. Takket være nummerpladegenkendelsen er der ingen automat, du skal nå fra bilen.",
    "red.h2b": "På toget og ind i Zermatt",
    "red.p3": "Elevatorer og ramper forbinder parkeringshuset med perronen, og shuttletogene medtager kørestole. I Zermatt kan du bestille en eltaxa videre til dit hotel. Medbring det, du har brug for til et nemt skifte:",
    "red.li1": "Din parkeringsbekræftelse (knyttet til din nummerplade)",
    "red.li2": "Et gyldigt handicapparkeringskort til de tilgængelige pladser",
    "red.f1k": "Adgang",
    "red.f1v": "Trinfri, elevatorer til perron",
    "red.f2k": "Pladser",
    "red.f2v": "Tilgængelige pladser ved elevatorerne",
    "red.f3k": "Tog",
    "red.f3v": "Kørestolsvenligt shuttletog",
    "red.f4k": "Medbring",
    "red.f4v": "Bekræftelse + handicapkort",
