    "info.guarantee": "Zermatt'a araç girişi yasaktır. Aracınızı Täsch'teki Matterhorn Terminal'de bırakın ve mekik trene binin — yaklaşık 20 dakikada bir kalkar ve Zermatt'a yaklaşık 12 dakikada ulaşır.",
