    "gh.title": "Otopark bilgileri",
    "gh.lead": "Täsch'teki Matterhorn Terminal'de park etme ve otomobilsiz Zermatt'a ulaşma hakkında bilmeniz gereken her şey — nasıl gelinir, elektrikli aracınızı nasıl şarj edersiniz ve mekik tren nasıl çalışır.",
    "gh.banner": "Zermatt otomobilsizdir. Her araç Täsch'te durur: Matterhorn Terminal'de park edin ve mekik tren ya da taksiyle devam edin.",
    "gh.car.d": "Vadi yolundan Täsch'e gelin, kapalı terminalde park edin ve trene binin. Güzergah ve yükseklik sınırı.",
    "gh.charging.d": "Terminalde 131 şarj istasyonu. Şarj istasyonlu bir yer ayırtın ve Zermatt'tayken aracınızı şarj edin.",
    "gh.train.d": "Mekik tren Täsch ile Zermatt arasını yaklaşık 12 dakikada alır ve yaklaşık 20 dakikada bir sefer yapar. Biletleri otopark rezervasyonunuza ekleyebilir veya terminalden alabilirsiniz.",
    "gh.reduced.d": "Asansörlere yakın erişilebilir yerler ve mekik tren peronuna basamaksız erişim.",
    "car.h1": "Arabayla varış",
    "car.lead": "Täsch'teki Matterhorn Terminal'e nasıl gidilir ve Zermatt için arabayı nereye bırakırsınız.",
    "car.p1": "Zermatt otomobilsizdir, bu yüzden Matterhorn'a yapılan her kara yolculuğu Täsch'te biter. Rhône vadisinden kanton yolunu izleyerek Visp, St. Niklaus ve Randa üzerinden yukarı çıkarsınız; Matterhorn Terminal, vadi yolunun sonunda Täsch istasyonunun hemen yanındadır. Navigasyonu “Matterhorn Terminal Täsch” olarak ayarlayın, sizi doğrudan girişe götürür.",
    "car.h2a": "Terminalde park etme",
    "car.p2": "Terminal, yaklaşık 2.100 araçlık çok katlı kapalı bir otoparktır. Çevrimiçi rezervasyonda plakanız kaydedilir; böylece varışta bariyer otomatik açılır ve doğrudan park yerine gidersiniz — kâğıt bilet saklamanıza gerek yok. Standart bir yer için “Otopark”, aracınızı şarj etmek istiyorsanız “Şarj istasyonlu otopark” seçeneğini seçin.",
    "car.callout": "Yola çıkmadan önce çevrimiçi rezervasyon yapın. Plakanız bariyerde tanınır; giriş ve çıkışta ödeme makinesine uğramanız gerekmez.",
    "car.h2b": "Yükseklik sınırı",
    "car.p3": "Azami araç yüksekliği 2,30 metredir; bu, tavan kutusu olmayan normal otomobiller, station wagon'lar ve çoğu SUV için yeterlidir. Karavan gibi daha yüksek araçlar kapalı otoparkı kullanamaz.",
    "car.h2c": "Arabadan Zermatt'a",
    "car.p4": "Mekik tren peronu otoparka iki dakika yürüme mesafesindedir. Otomobilsiz Zermatt'a giden trenler yaklaşık 20 dakikada bir kalkar ve yaklaşık 12 dakika sürer; taksiler ve elektrikli otel servisleri de terminalden yolcu alır.",
    "car.f1k": "Otopark",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Yerler",
    "car.f2v": "≈ 2.100, kapalı",
    "car.f3k": "Maks. yükseklik",
    "car.f3v": "2,30 m",
    "car.f4k": "Zermatt'a",
    "car.f4v": "Mekik tren, ≈ 12 dk",
    "chg.h1": "Elektrikli araçlar ve şarj",
    "chg.lead": "Zermatt ziyaretiniz sırasında elektrikli aracınızı şarj etme ve bir şarj yeri ayırtma.",
    "chg.p1": "Matterhorn Terminal, kapalı otoparka yerleştirilmiş 131 şarj istasyonuyla Alpler'in en büyük şarj noktalarından biridir. İstasyonlar sabit kablo ve Type 2 fişle 22 kW'a (AC) kadar güç verir; böylece çoğu elektrikli araç siz Zermatt'tayken rahatça şarj olur.",
    "chg.h2a": "Bir şarj yeri ayırtma",
    "chg.p2": "Rezervasyon sırasında standart otopark yerine “Şarj istasyonlu otopark” seçeneğini seçin. Böylece konaklamanız boyunca bir şarj cihazının yanında yeriniz olur ve varışta boş şarj cihazı aramanız gerekmez.",
    "chg.callout": "Rezervasyon formunun ilk adımında “Şarj istasyonlu otopark” seçeneğini seçin; böylece tarihleriniz için şarj cihazı garanti olur.",
    "chg.h2b": "Enerjinin ödenmesi",
    "chg.p3": "Rezervasyonunuz otopark yerini ve şarj yerini kapsar. Gerçekte çektiğiniz enerji, istasyonda QR koduyla ayrıca faturalandırılır — kredi kartı, TWINT, Apple Pay ve Google Pay kabul edilir — böylece yalnızca kullandığınız elektriği ödersiniz.",
    "chg.f1k": "İstasyonlar",
    "chg.f1v": "131, otoparkta",
    "chg.f2k": "Güç",
    "chg.f2v": "22 kW AC'ye kadar, Type 2",
    "chg.f3k": "Rezervasyon",
    "chg.f3v": "“Şarj istasyonlu otopark”",
    "chg.f4k": "Enerji",
    "chg.f4v": "İstasyonda QR ile ödenir",
    "trn.h1": "Zermatt'a ulaşım",
    "trn.lead": "Mekik trenin Täsch ile otomobilsiz Zermatt'ı nasıl bağladığı.",
    "trn.p1": "Zermatt'ta içten yanmalı motorlu araçlar yasak olduğundan yolculuğun son kısmı trenle yapılır. Mekik tren, sabahın erken saatlerinden gece geç saatlere kadar Täsch ile Zermatt arasında yaklaşık 20 dakikada bir çalışır ve mesafeyi yaklaşık 12 dakikada kat eder.",
    "trn.h2a": "Biletler ve peron",
    "trn.p2": "Peron otoparkın hemen yanındadır — yol geçmeye gerek yoktur, raylara asansör ve rampayla inilir. En kolayı mekik tren biletlerini otopark rezervasyonunuza eklemektir; biletleri terminaldeki makinelerden veya bir demiryolu uygulamasından da alabilirsiniz.",
    "trn.callout": "Zermatt Shuttle biletlerinizi otoparkı ayırttığınız formda ekleyin — ya da daha sonra terminaldeki makinelerden alın.",
    "trn.h2b": "Bagaj ve devam yolculuğu",
    "trn.p3": "Her iki peronda da bagaj arabaları vardır ve Zermatt'taki birçok otel, misafirlerini varışta karşılamak için elektrikli taksi gönderir. Trenlerin ve peronların kalabalık olduğu yoğun sezonda biraz zaman payı bırakın.",
    "trn.f1k": "Hat",
    "trn.f1v": "Täsch ⇄ Zermatt mekik",
    "trn.f2k": "Sıklık",
    "trn.f2v": "≈ 20 dakikada bir",
    "trn.f3k": "Yolculuk",
    "trn.f3v": "≈ 12 dk",
    "trn.f4k": "Biletler",
    "trn.f4v": "Çevrimiçi veya terminalde",
    "red.h1": "Kısıtlı hareketlilik ve erişilebilirlik",
    "red.lead": "Terminalde erişilebilir otopark ve mekik trene basamaksız erişim.",
    "red.p1": "Matterhorn Terminal basamaksız tasarlanmıştır. Erişilebilir otopark yerleri, sizi merdivensiz doğrudan mekik tren peronuna indiren asansörlerin yakınındadır.",
    "red.h2a": "Asansörlere yakın park etme",
    "red.p2": "Her zamanki gibi çevrimiçi standart bir yer ayırtın; engelli park kartınız varsa varışta asansörlerin yanındaki işaretli engelli park yerine park edin. Plaka tanıma sayesinde arabadan herhangi bir makineye uzanmanız gerekmez.",
    "red.h2b": "Trene ve Zermatt'a",
    "red.p3": "Asansörler ve rampalar otoparkı peronla bağlar ve mekik trenler tekerlekli sandalyeleri alır. Zermatt'ta otelinize devam etmek için elektrikli taksi ısmarlanabilir. Sorunsuz bir aktarma için ihtiyacınız olanı yanınıza alın:",
    "red.li1": "Otopark onayınız (plakanıza bağlı)",
    "red.li2": "Erişilebilir yerler için geçerli bir engelli park kartı",
    "red.f1k": "Erişim",
    "red.f1v": "Basamaksız, perona asansörler",
