    "hero.title": "在 Täsch 预订停车位<br>前往 Zermatt",
    "hero.subtitle": "在 Täsch 的 Matterhorn Terminal 预订车位，乘坐接驳列车前往无车的 Zermatt。",
    "info.title": "停车换乘前往 Zermatt",
    "info.guarantee": "Zermatt 是无车小镇。把车停在 Täsch 的 Matterhorn Terminal，然后乘坐接驳列车——约每 20 分钟一班，约 12 分钟即可到达 Zermatt。",
    "info.process": "只需几步即可在线预订。付款后，您会收到确认邮件。您的车牌会录入系统，道闸自动识别后抬杆，抵达时可直接驶入室内停车楼——不用担心停车票丢失。",
    "info.extra": "该换乘站约有 2,100 个室内车位和 131 个充电桩。预订时选择“带充电桩的停车位”，即可为您的电动车预留一个充电车位。",
