    "gh.title": "停车信息",
    "gh.lead": "关于在 Täsch 的 Matterhorn Terminal 停车以及前往无车 Zermatt 的一切须知——如何抵达、如何为电动车充电，以及接驳列车如何运作。",
    "gh.banner": "Zermatt 是无车小镇。所有车辆都在 Täsch 停下：把车停在 Matterhorn Terminal，再乘坐接驳列车或出租车继续前行。",
    "gh.car.d": "沿山谷公路抵达 Täsch，停在室内换乘站并搭乘列车。路线与限高。",
    "gh.charging.d": "换乘站设有 131 个充电桩。预订带充电桩的车位，在 Zermatt 游玩期间即可充电。",
    "gh.train.d": "接驳列车约 12 分钟连接 Täsch 与 Zermatt，约每 20 分钟一班。车票可随停车一并预订，也可在换乘站购买。",
    "gh.reduced.d": "靠近电梯的无障碍车位，以及通往接驳列车站台的无台阶通道。",
    "car.h1": "自驾抵达",
    "car.lead": "如何驾车前往 Täsch 的 Matterhorn Terminal，以及前往 Zermatt 时把车停在哪里。",
    "car.p1": "Zermatt 是无车小镇，因此每一次驶向马特洪峰的自驾都止于 Täsch。从罗讷河谷出发，沿州级公路经 Visp、St. Niklaus 和 Randa 向上行驶；Matterhorn Terminal 就位于山谷公路尽头的 Täsch 车站旁。将导航设为“Matterhorn Terminal Täsch”，即可直接抵达入口。",
    "car.h2a": "在换乘站停车",
    "car.p2": "换乘站是一座约有 2,100 个车位的多层室内停车楼。在线预订时会记录您的车牌，抵达时道闸自动打开，直接驶向车位——无需保留纸质取票。普通车位选择“停车”，如需充电则选择“带充电桩的停车位”。",
    "car.callout": "出发前在线预订。道闸会自动识别车牌，进出时都无需到缴费机付款。",
    "car.h2b": "限高",
    "car.p3": "车辆限高 2.30 米，普通轿车、旅行车以及大多数未装车顶箱的 SUV 均可驶入。房车等更高的车辆无法进入室内停车楼。",
    "car.h2c": "从车到 Zermatt",
    "car.p4": "接驳列车站台距停车楼步行两分钟。前往无车 Zermatt 的列车约每 20 分钟一班，约 12 分钟；出租车和酒店电动接驳车也在换乘站接客。",
    "car.f1k": "停车场",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "车位",
    "car.f2v": "≈ 2,100，室内",
    "car.f3k": "最大高度",
    "car.f3v": "2.30 米",
    "car.f4k": "前往 Zermatt",
    "car.f4v": "接驳列车，约 12 分钟",
    "chg.h1": "电动车与充电",
    "chg.lead": "在游览 Zermatt 期间为电动车充电，以及如何预留充电车位。",
    "chg.p1": "Matterhorn Terminal 是阿尔卑斯山最大的充电点之一，室内停车楼内设有 131 个充电桩。充电桩提供最高 22 kW（交流）功率，配固定电缆和 Type 2 插头，多数电动车都能在您上山游览 Zermatt 时从容充电。",
    "chg.h2a": "预留充电车位",
    "chg.p2": "预订时请选择“带充电桩的停车位”，而非普通停车。这会在整个停留期间为您预留充电桩旁的车位，抵达时无需寻找空闲设备。",
    "chg.callout": "在预订表单第一步选择“带充电桩的停车位”，即可确保您的日期有充电桩可用。",
    "chg.h2b": "电费支付",
    "chg.p3": "您的预订涵盖停车位和充电车位。实际使用的电量在充电桩处通过二维码单独结算——支持信用卡、TWINT、Apple Pay 和 Google Pay——因此您只需为所用电量付费。",
    "chg.f1k": "充电桩",
    "chg.f1v": "131 个，位于停车楼内",
