    "trn.h1": "如何前往 Zermatt",
    "trn.lead": "接驳列车如何连接 Täsch 与无车 Zermatt。",
    "trn.p1": "由于 Zermatt 禁止燃油车，旅程的最后一段需乘坐火车。接驳列车从清晨运行至深夜，往返于 Täsch 与 Zermatt 之间，约每 20 分钟一班，约 12 分钟即可走完全程。",
    "trn.h2a": "车票与站台",
    "trn.p2": "站台就在停车楼旁——无需横穿马路，设有通往轨道的电梯和坡道。最方便的方式是把接驳车票加入停车预订；也可在换乘站的售票机或铁路 App 购买。",
    "trn.callout": "预订停车时即可在同一表单中添加 Zermatt Shuttle 车票——也可以之后在换乘站的售票机购买。",
    "trn.h2b": "行李与后续行程",
    "trn.p3": "两侧站台都备有行李推车，Zermatt 的许多酒店会派电动出租车在 Zermatt 一侧迎接客人。旺季列车和站台较为拥挤，请预留一些余量。",
    "trn.f1k": "线路",
    "trn.f1v": "Täsch ⇄ Zermatt 接驳",
    "trn.f2k": "班次",
    "trn.f2v": "约每 20 分钟",
