    "trn.f4v": "在线或换乘站购买",
    "red.h1": "行动不便与无障碍",
    "red.lead": "换乘站的无障碍停车以及通往接驳列车的无台阶通道。",
    "red.p1": "Matterhorn Terminal 采用无台阶设计。无障碍车位靠近电梯，可不经楼梯直接下到接驳列车站台。",
    "red.h2a": "在电梯附近停车",
    "red.p2": "照常在线预订普通车位；如持有残障停车证，抵达时请停在电梯附近划定的无障碍车位。道闸自动识别车牌，无需从车内够取任何机器。",
    "red.h2b": "登上列车前往 Zermatt",
    "red.p3": "电梯和坡道连接停车楼与站台，接驳列车可搭载轮椅。在 Zermatt 可预订电动出租车前往酒店。请携带顺利换乘所需的物品：",
    "red.li1": "您的停车确认（与车牌绑定）",
