    "info.guarantee": "Zermatt は車両乗り入れ禁止の村です。Täsch の Matterhorn Terminal に車を停め、シャトル列車をご利用ください。約20分間隔で運行し、Zermatt まで約12分で到着します。",
    "info.process": "オンラインで数クリックで予約できます。お支払い後、予約内容を記載した確認メールが届きます。ナンバープレートがゲートに登録されるため、ナンバー認識により到着時にそのまま屋根付き駐車場へ入れます。紛失する券はありません。",
