    "gh.title": "駐車案内",
    "gh.lead": "Täsch の Matterhorn Terminal での駐車と、カーフリーの Zermatt への行き方に関するすべて——アクセス方法、電気自動車の充電、シャトル列車の仕組み。",
    "gh.banner": "Zermatt は車両乗り入れ禁止です。すべての車は Täsch で停まります。Matterhorn Terminal に駐車し、シャトル列車かタクシーで進んでください。",
    "gh.car.d": "谷沿いの道路で Täsch へ向かい、屋根付きターミナルに駐車して列車に乗車。ルートと高さ制限。",
    "gh.charging.d": "ターミナルに充電スタンド131基。充電スタンド付きのスペースを予約すれば、Zermatt 滞在中に充電できます。",
    "gh.train.d": "シャトル列車は Täsch と Zermatt を約12分で結び、約20分間隔で運行。乗車券は駐車予約と一緒に追加するか、ターミナルで購入できます。",
    "gh.reduced.d": "エレベーター近くのバリアフリースペースと、シャトル列車ホームへの段差のないアクセス。",
    "car.h1": "車での到着",
    "car.lead": "Täsch の Matterhorn Terminal への行き方と、Zermatt へ向かう際の車の停め方。",
    "car.p1": "Zermatt は車両乗り入れ禁止のため、マッターホルンへの車の旅はすべて Täsch で終わります。ローヌ谷から州道を Visp、St. Niklaus、Randa 経由で上っていくと、Matterhorn Terminal は谷沿いの道路の終点、Täsch 駅のすぐ隣にあります。ナビを「Matterhorn Terminal Täsch」に設定すれば、入口まで直接案内します。",
    "car.h2a": "ターミナルでの駐車",
    "car.p2": "ターミナルは約2,100台分の多層式屋根付き駐車場です。オンライン予約時にナンバーが登録されるため、到着時にゲートが自動で開き、そのままスペースへ進めます——保管する紙の券はありません。通常のスペースは「駐車」を、充電が必要な場合は「充電スタンド付き駐車」を選択してください。",
    "car.callout": "出発前にオンラインで予約しましょう。ゲートでナンバーが認識されるので、入出庫時に精算機に寄る必要がありません。",
    "car.h2b": "高さ制限",
    "car.p3": "車両の高さ制限は2.30メートルです。一般的な乗用車、ステーションワゴン、ルーフボックスのないほとんどのSUVが入庫できます。キャンピングカーなど、これより高い車両は屋根付き駐車場をご利用いただけません。",
    "car.h2c": "車から Zermatt へ",
    "car.p4": "シャトル列車のホームは駐車場から徒歩2分です。カーフリーの Zermatt への列車は約20分間隔で運行し、約12分かかります。タクシーやホテルの電動送迎車もターミナルで乗車できます。",
    "car.f1k": "駐車場",
