    "chg.h1": "電気自動車と充電",
    "chg.lead": "Zermatt 観光中の電気自動車の充電と、充電スペースの予約方法。",
    "chg.p1": "Matterhorn Terminal はアルプス有数の充電拠点で、屋根付き駐車場内に131基の充電スタンドを備えています。スタンドは固定ケーブルとType 2プラグで最大22 kW（AC）を供給するため、Zermatt に上っている間にほとんどの電気自動車が余裕をもって充電できます。",
    "chg.h2a": "充電スペースの予約",
    "chg.p2": "ご予約の際は、通常の駐車ではなく「充電スタンド付き駐車」を選択してください。これで滞在中ずっと充電器の隣のスペースが確保され、到着時に空きを探す必要がありません。",
    "chg.callout": "予約フォームの最初のステップで「充電スタンド付き駐車」を選べば、ご希望の日程で充電器を確保できます。",
    "chg.h2b": "電力料金の支払い",
    "chg.p3": "ご予約には駐車スペースと充電スペースが含まれます。実際に使用した電力はスタンドでQRコードにより別途精算されます——クレジットカード、TWINT、Apple Pay、Google Pay に対応——ので、使った分だけお支払いいただきます。",
