    "trn.h1": "Zermatt への行き方",
    "trn.lead": "シャトル列車が Täsch とカーフリーの Zermatt をどう結ぶか。",
    "trn.p1": "Zermatt は内燃機関車を禁止しているため、旅の最後の区間は鉄道です。シャトル列車は早朝から深夜まで Täsch と Zermatt の間を約20分間隔で運行し、約12分で走破します。",
    "trn.h2a": "切符とホーム",
    "trn.p2": "ホームは駐車場のすぐ隣にあり、道路を渡る必要はありません。線路まではエレベーターとスロープがあります。シャトルの乗車券は駐車予約に追加するのが最も便利ですが、ターミナルの券売機や鉄道アプリでも購入できます。",
    "trn.callout": "駐車場を予約するフォームで Zermatt Shuttle の乗車券も一緒に追加できます。後からターミナルの券売機で購入することも可能です。",
    "trn.h2b": "荷物と乗り継ぎ",
    "trn.p3": "両側のホームに手荷物カートがあり、Zermatt の多くのホテルは到着したゲストを電動タクシーで迎えに来ます。列車やホームが混雑するハイシーズンは、時間に余裕をもってお越しください。",
