    "red.h1": "移動制約とバリアフリー",
    "red.lead": "ターミナルのバリアフリー駐車と、シャトル列車への段差のないアクセス。",
    "red.p1": "Matterhorn Terminal は段差のない設計です。バリアフリー駐車スペースはエレベーターの近くにあり、階段を使わずにシャトル列車のホームまで直接下りられます。",
    "red.h2a": "エレベーター近くの駐車",
    "red.p2": "通常どおりオンラインで一般スペースを予約してください。障害者用駐車許可証をお持ちの場合は、到着時にエレベーター付近の指定スペースに駐車してください。ナンバー認識のため、車内から精算機に手を伸ばす必要はありません。",
