    "info.process": "몇 번의 클릭으로 온라인 예약이 가능합니다. 결제 후 예약 내용이 담긴 확인 이메일을 받습니다. 번호판이 차단기에 등록되어, 번호판 인식 덕분에 도착 시 곧바로 실내 주차장으로 들어갈 수 있습니다. 분실할 티켓이 없습니다.",
