    "gh.lead": "Täsch의 Matterhorn Terminal 주차와 차 없는 Zermatt로 가는 방법에 대한 모든 것 — 오는 방법, 전기차 충전, 그리고 셔틀 열차의 작동 방식.",
    "gh.banner": "Zermatt는 차량이 없는 곳입니다. 모든 차는 Täsch에서 멈춥니다. Matterhorn Terminal에 주차하고 셔틀 열차나 택시로 이동하세요.",
    "gh.car.d": "계곡 도로를 따라 Täsch로 와서 실내 터미널에 주차하고 열차에 오르세요. 경로와 높이 제한.",
    "gh.charging.d": "터미널에 충전소 131개. 충전소가 있는 자리를 예약하고 Zermatt에 머무는 동안 충전하세요.",
    "gh.train.d": "셔틀 열차가 Täsch와 Zermatt를 약 12분 만에 연결하며 약 20분 간격으로 운행합니다. 승차권은 주차 예약에 추가하거나 터미널에서 구입하세요.",
    "gh.reduced.d": "엘리베이터 가까이의 장애인 주차 자리와 셔틀 열차 승강장으로의 무단차 접근.",
    "car.h1": "자동차로 도착",
    "car.lead": "Täsch의 Matterhorn Terminal로 가는 방법과 Zermatt를 위해 차를 둘 곳.",
    "car.p1": "Zermatt는 차량이 없는 곳이므로 마터호른으로 가는 모든 자동차 여행은 Täsch에서 끝납니다. 론 계곡에서 주 도로를 따라 Visp, St. Niklaus, Randa를 거쳐 올라오면, Matterhorn Terminal은 계곡 도로 끝의 Täsch 역 바로 옆에 있습니다. 내비게이션을 'Matterhorn Terminal Täsch'로 설정하면 입구까지 곧바로 안내합니다.",
    "car.h2a": "터미널 주차",
    "car.p2": "터미널은 약 2,100대 규모의 다층 실내 주차장입니다. 온라인 예약 시 번호판이 저장되어, 도착하면 차단기가 자동으로 열리고 곧바로 자리로 이동합니다 — 보관할 종이 티켓이 없습니다. 일반 자리는 '주차'를, 충전이 필요하면 '충전소 포함 주차'를 선택하세요.",
    "car.callout": "출발 전에 온라인으로 예약하세요. 차단기가 번호판을 인식하므로 입출차 시 정산기에 들를 필요가 없습니다.",
    "car.h2b": "높이 제한",
    "car.p3": "차량 높이 제한은 2.30미터입니다. 일반 승용차, 왜건, 루프 박스가 없는 대부분의 SUV는 이용할 수 있습니다. 캠핑카처럼 더 높은 차량은 실내 주차장을 이용할 수 없습니다.",
    "car.h2c": "차에서 Zermatt로",
    "car.p4": "셔틀 열차 승강장은 주차장에서 도보 2분 거리입니다. 차 없는 Zermatt로 가는 열차는 약 20분 간격으로 운행하며 약 12분이 걸립니다. 택시와 호텔 전기 셔틀도 터미널에서 승객을 태웁니다.",
    "car.f1k": "주차장",
    "car.f1v": "Matterhorn Terminal, Täsch",
