    "car.f3v": "2.30 m",
    "car.f4k": "Zermatt로",
    "car.f4v": "셔틀 열차, ≈ 12분",
    "chg.h1": "전기차와 충전",
    "chg.lead": "Zermatt 방문 중 전기차 충전과 충전 공간 예약 방법.",
    "chg.p1": "Matterhorn Terminal은 알프스 최대 규모의 충전 장소 중 하나로, 실내 주차장 안에 131개의 충전소가 있습니다. 충전소는 고정 케이블과 Type 2 플러그로 최대 22 kW(AC)를 제공하여, Zermatt에 올라가 있는 동안 대부분의 전기차가 여유롭게 충전됩니다.",
    "chg.h2a": "충전 공간 예약",
    "chg.p2": "예약 시 일반 주차 대신 '충전소 포함 주차'를 선택하세요. 그러면 체류 기간 내내 충전기 옆 자리가 예약되어, 도착 시 빈 충전기를 찾을 필요가 없습니다.",
    "chg.callout": "예약 양식 첫 단계에서 '충전소 포함 주차'를 선택하면 원하는 날짜에 충전기가 확보됩니다.",
