    "trn.h1": "Zermatt 가는 방법",
    "trn.lead": "셔틀 열차가 Täsch와 차 없는 Zermatt를 어떻게 연결하는가.",
    "trn.p1": "Zermatt는 내연기관 차량을 금지하므로 여정의 마지막 구간은 열차입니다. 셔틀 열차는 이른 아침부터 늦은 밤까지 Täsch와 Zermatt 사이를 약 20분 간격으로 운행하며, 이 거리를 약 12분에 주파합니다.",
    "trn.h2a": "티켓과 승강장",
    "trn.p2": "승강장은 주차장 바로 옆에 있어 도로를 건널 필요가 없고, 선로까지 엘리베이터와 경사로가 있습니다. 셔틀 승차권은 주차 예약에 추가하는 것이 가장 편리하며, 터미널 발권기나 철도 앱에서도 구입할 수 있습니다.",
    "trn.callout": "주차를 예약하는 양식에서 Zermatt Shuttle 승차권도 함께 추가하세요. 나중에 터미널 발권기에서 구입해도 됩니다.",
    "trn.h2b": "수하물과 이후 이동",
    "trn.p3": "양쪽 승강장에 수하물 카트가 있으며, Zermatt의 많은 호텔이 도착한 손님을 맞이하기 위해 전기 택시를 보냅니다. 열차와 승강장이 붐비는 성수기에는 여유 시간을 두세요.",
