    "red.p1": "Matterhorn Terminal은 단차 없이 설계되었습니다. 접근 가능한 주차 자리는 엘리베이터 가까이에 있어, 계단 없이 셔틀 열차 승강장까지 곧바로 내려갈 수 있습니다.",
    "red.h2a": "엘리베이터 근처 주차",
    "red.p2": "평소처럼 온라인으로 일반 자리를 예약하세요. 장애인 주차 표지가 있으면 도착 시 엘리베이터 근처의 표시된 장애인 주차 자리에 주차하세요. 번호판 인식 덕분에 차에서 기계를 조작할 필요가 없습니다.",
