/* ======================================================================
   Täsch Parking — pricing & booking logic
   Parking and parking with e-charging cost the same:
     CHF 32 / day  (CHF 30 / day for 8+ days); the energy itself is paid at the charger
   ====================================================================== */
const PRICE = {
  parking:  { base: 32, longBase: 30 },
  charging: { base: 32, longBase: 30 },   // same price as regular parking (per request)
};
const LONG_STAY_DAYS = 8;          // discounted rate from the 8th day on
const TICKET_FULL = 22;            // Zermatt Shuttle return ticket (CHF)
const TICKET_HALF = 11;            // half fare (Half Fare travelcard / children 6–15 / dogs over 30 cm)
const TICKET_MAX = 20;             // per fare type

const CURRENCY = "CHF";
function money(n) { return CURRENCY + " " + n; }

const LOCALE = { en: "en-GB", de: "de-DE", it: "it-IT", fr: "fr-FR", es: "es-ES", hu: "hu-HU", pl: "pl-PL", ro: "ro-RO", cs: "cs-CZ", nl: "nl-NL", sl: "sl-SI", pt: "pt-PT", hr: "hr-HR", sk: "sk-SK", sr: "sr-RS", uk: "uk-UA", ru: "ru-RU", da: "da-DK", nb: "nb-NO", tr: "tr-TR", zh: "zh-CN", ja: "ja-JP", ko: "ko-KR", hi: "hi-IN", ar: "ar-EG-u-nu-latn" };

/* the earliest bookable day is tomorrow (period may start no sooner) — computed on
   every use, so a tab left open past midnight doesn't start allowing same-day bookings */
function minDate() {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
function validEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || "").trim());
}

/* pick the visitor's language from the browser, falling back to English */
const RTL_LANGS = ["ar", "he", "fa", "ur"];
const LANG_ALIAS = { no: "nb", nn: "nb", bs: "hr", sh: "sr", iw: "he", in: "id" };
/* ?lang=xx wins over everything: it is the URL search engines index */
function langFromUrl() {
  const q = new URLSearchParams(location.search).get("lang");
  if (!q) return null;
  const base = String(q).toLowerCase().split("-")[0];
  const mapped = LANG_ALIAS[base] || base;
  return I18N[mapped] ? mapped : null;
}

function detectLang() {
  const fromUrl = langFromUrl();
  if (fromUrl) return fromUrl;
  const supported = Object.keys(I18N);
  const prefs = navigator.languages && navigator.languages.length
    ? navigator.languages
    : [navigator.language || "en"];
  for (const raw of prefs) {
    const base = String(raw).toLowerCase().split("-")[0];
    const mapped = LANG_ALIAS[base] || base;
    if (supported.includes(mapped)) return mapped;
  }
  return "en";
}

/* <title> and <meta description> are built from copy that is already translated,
   so adding a language never means writing new marketing strings. */
const PAGE_META = {
  "index.html":                    { t: "hero.title", d: "hero.subtitle" },
  "getting-here.html":             { t: "gh.title",   d: "gh.lead" },
  "arrival-car.html":              { t: "car.h1",     d: "car.lead" },
  "arrival-charging.html":         { t: "chg.h1",     d: "chg.lead" },
  "arrival-train.html":            { t: "trn.h1",     d: "trn.lead" },
  "arrival-reduced-mobility.html": { t: "red.h1",     d: "red.lead" },
};
const SITE_NAME = "Täsch Parking";

function currentPage() {
  const f = location.pathname.split("/").pop();
  return !f || f === "" ? "index.html" : f;
}

function setMetaTag(sel, attr, value) {
  let el = document.head.querySelector(sel);
  if (!el) {
    el = document.createElement("meta");
    const m = sel.match(/\[(name|property)="([^"]+)"\]/);
    if (m) el.setAttribute(m[1], m[2]);
    document.head.appendChild(el);
  }
  el.setAttribute(attr, value);
}

function applyMeta() {
  const meta = PAGE_META[currentPage()];
  if (!meta) return;
  // <br> becomes a space, except between CJK characters where a space is wrong
  const CJK = "\\u3040-\\u30FF\\u3400-\\u4DBF\\u4E00-\\u9FFF";
  const cjkGap = new RegExp("([" + CJK + "]) ([" + CJK + "])", "g");
  const strip = (s) => s
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .replace(cjkGap, "$1$2")
    .trim();
  const title = strip(t(meta.t));
  const desc  = strip(t(meta.d));
  const full  = currentPage() === "index.html"
    ? SITE_NAME + " — " + title
    : title + " — " + SITE_NAME;

  document.title = full;
  setMetaTag('meta[name="description"]', "content", desc);
  setMetaTag('meta[property="og:title"]', "content", full);
  setMetaTag('meta[property="og:description"]', "content", desc);
  setMetaTag('meta[property="og:locale"]', "content", (LOCALE[lang] || "en-GB").split("-").slice(0, 2).join("_"));
  setMetaTag('meta[property="og:type"]', "content", "website");
  setMetaTag('meta[property="og:site_name"]', "content", SITE_NAME);

  // canonical points at the URL for this exact language
  let link = document.head.querySelector('link[rel="canonical"]');
  if (!link) {
    link = document.createElement("link");
    link.rel = "canonical";
    document.head.appendChild(link);
  }
  // /index.html and / are the same page; hreflang tags and the sitemap use "/"
  const base = location.origin + location.pathname.replace(/\/index\.html$/, "/");
  link.href = lang === "en" ? base : base + "?lang=" + lang;
  setMetaTag('meta[property="og:url"]', "content", link.href);
}

/* keep ?lang= in the address bar so the page can be shared and indexed */
function syncLangUrl() {
  const url = new URL(location.href);
  if (lang === "en") url.searchParams.delete("lang");
  else url.searchParams.set("lang", lang);
  history.replaceState(null, "", url.pathname + url.search + url.hash);
}

let lang = detectLang();

/* ---------- localStorage persistence ---------- */
function saveState() {
  const state = { lang, booking, bookStep };
  try { localStorage.setItem("taesch_booking_state", JSON.stringify(state)); } catch (e) {}
}

function loadState() {
  let stored = null;
  try { stored = localStorage.getItem("taesch_booking_state"); } catch (e) {}
  if (stored) {
    try {
      const state = JSON.parse(stored);
      // an explicit ?lang= in the URL outranks whatever was stored last time
      if (!langFromUrl() && state.lang && I18N[state.lang]) lang = state.lang;
      booking = sanitizeBooking(state.booking);
      // never allow a stored period that has slipped into the past
      if (booking.start && booking.start < minDate()) { booking.start = ""; booking.end = ""; }
      if (booking.end && booking.end < booking.start) booking.end = "";
      bookStep = [1, 2, 3].includes(state.bookStep) ? state.bookStep : 1;
      // a later step may only be restored while everything before it is still valid
      if (bookStep > 1 && !validBooking(booking)) bookStep = 1;
      if (bookStep > 2 && !validEmail(booking.email)) bookStep = 2;
      return true;
    } catch (e) {
      console.error("Failed to load state:", e);
      return false;
    }
  }
  return false;
}

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

const t = (key) => (I18N[lang] && I18N[lang][key]) || I18N.en[key] || key;

/* ---------- i18n / render ---------- */
function applyI18n() {
  $$("[data-i18n]").forEach((el) => {
    const val = t(el.dataset.i18n);
    if (el.hasAttribute("data-i18n-html")) el.innerHTML = val;
    else el.textContent = val;
  });
  $$("[data-i18n-aria]").forEach((el) => el.setAttribute("aria-label", t(el.dataset.i18nAria)));

  if (weatherData) renderWeather();
  renderBooking();
  document.documentElement.lang = lang;
}

/* ---------- menus ---------- */
function closeMenus() {
  $$(".menu-open").forEach((el) => {
    el.classList.remove("menu-open");
    const btn = el.querySelector("[aria-expanded]");
    if (btn) btn.setAttribute("aria-expanded", "false");
  });
}

function toggleMenu(container) {
  const isOpen = container.classList.contains("menu-open");
  closeMenus();
  if (!isOpen) {
    container.classList.add("menu-open");
    const btn = container.querySelector("[aria-expanded]");
    if (btn) btn.setAttribute("aria-expanded", "true");
  }
}

/* reflect the active language in the header badge, the menu and <html lang> */
function syncLangUI() {
  const badge = $("#langCode");
  if (badge) badge.textContent = lang.toUpperCase();
  $$("#langMenu .select-option").forEach((o) => {
    o.classList.toggle("is-active", o.dataset.lang === lang);
    o.setAttribute("aria-selected", String(o.dataset.lang === lang));
  });
  document.documentElement.setAttribute("lang", lang);
  document.documentElement.setAttribute("dir", RTL_LANGS.includes(lang) ? "rtl" : "ltr");
}

function setLang(l) {
  lang = l;
  syncLangUI();
  closeMenus();
  applyI18n();
  applyMeta();
  syncLangUrl();
  saveState();
}

/* ======================================================================
   Booking form (one reservation: option + period + plate, shuttle tickets, e-mail)
   ====================================================================== */
function newBooking(seed) {
  return Object.assign({
    option: "parking",
    start: "", end: "",
    plate: "",
    tickets: true, tFull: 1, tHalf: 0,   // shuttle tickets chosen on step 2, on by default
    email: "", terms: true,
  }, seed || {});
}

/* restored state comes from localStorage — rebuild it field by field so tampered or
   stale values can't break the price maths or end up in the markup */
function sanitizeBooking(raw) {
  const b = Object.assign(newBooking(), raw && typeof raw === "object" ? raw : {});
  const qty = (v) => Math.max(0, Math.min(TICKET_MAX, Math.floor(Number(v)) || 0));
  return {
    option: b.option === "charging" ? "charging" : "parking",
    start: ISO_DATE.test(b.start) ? b.start : "",
    end: ISO_DATE.test(b.end) ? b.end : "",
    plate: String(b.plate || "").slice(0, 32),
    tickets: !!b.tickets, tFull: qty(b.tFull), tHalf: qty(b.tHalf),
    email: String(b.email || "").slice(0, 254),
    terms: !!b.terms,
  };
}

let booking = newBooking();
let bookStep = 1; // 1 = parking details, 2 = shuttle tickets + e-mail, 3 = summary & payment

function esc(s) {
  return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

function fmtLong(iso, l = lang) {
  if (!iso) return "—";
  return new Date(iso + "T00:00:00").toLocaleDateString(LOCALE[l] || "en-GB", { weekday: "short", day: "numeric", month: "long", year: "numeric" });
}
/* compact form for the date pills — short weekday so you can see which day you picked */
function fmtField(iso, l = lang) {
  if (!iso) return "—";
  return new Date(iso + "T00:00:00").toLocaleDateString(LOCALE[l] || "en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric" });
}

/* ---------- pricing ---------- */
function stayDays(b) {
  if (!b.start || !b.end) return 0;
  const s = new Date(b.start + "T00:00:00");
  const e = new Date(b.end + "T00:00:00");
  const days = Math.round((e - s) / 86400000) + 1; // inclusive: 15→15 = 1 day
  return days > 0 ? days : 0;
}
function ratePerDay(option, days) {
  const p = PRICE[option] || PRICE.parking;
  return days >= LONG_STAY_DAYS ? p.longBase : p.base;
}
function parkingSubtotal(b) {
  const d = stayDays(b);
  return d > 0 ? ratePerDay(b.option, d) * d : 0;
}
function ticketsCount(b) {
  return b.tickets ? (b.tFull || 0) + (b.tHalf || 0) : 0;
}
function ticketsTotal(b) {
  return b.tickets ? (b.tFull || 0) * TICKET_FULL + (b.tHalf || 0) * TICKET_HALF : 0;
}
function bookingTotal(b) {
  return parkingSubtotal(b) + ticketsTotal(b);
}
/* "3 days" with each language's own plural rules (ru: 1 день / 2 дня / 5 дней).
   A form may carry {n} (CJK: 3日間) or start with "!" to be used as is (ar: يومان). */
function dayCountLabel(n) {
  let cat = n === 1 ? "one" : "other";
  try { cat = new Intl.PluralRules(LOCALE[lang] || "en-GB").select(n); } catch (e) {}
  const dict = I18N[lang] || {};
  const form = cat === "one" ? t("book.day") : (dict["book.days." + cat] || t("book.days"));
  if (form.startsWith("!")) return form.slice(1);
  return form.includes("{n}") ? form.replace("{n}", n) : n + " " + form;
}
function optionName(option, l = lang) {
  return option === "charging"
    ? (I18N[l] && I18N[l]["book.optCharging"]) || I18N.en["book.optCharging"]
    : (I18N[l] && I18N[l]["book.optParking"]) || I18N.en["book.optParking"];
}
function plateLabel(b) {
  return (b.plate || "").trim().toUpperCase();
}
function validBooking(b) {
  return !!b.start && !!b.end && b.start >= minDate() && b.end >= b.start && !!(b.plate && b.plate.trim());
}

function stepsHTML(active) {
  const item = (n, key) =>
    `<span class="bk-step${active === n ? " is-active" : ""}${active > n ? " is-done" : ""}"><b>${n}</b>${t(key)}</span>`;
  return `<div class="bk-steps">${item(1, "book.step1")}<span class="bk-step-line"></span>${item(2, "book.step2")}<span class="bk-step-line"></span>${item(3, "book.step3")}</div>`;
}

/* ── Custom range date-picker ── */
function dowLabels() {
  const loc = LOCALE[lang] || "en-GB";
  const build = (width) => {
    const fmt = new Intl.DateTimeFormat(loc, { weekday: width });
    const out = [];
    for (let i = 0; i < 7; i++) out.push(fmt.format(new Date(2024, 0, 1 + i)).replace(/\.$/, "")); // 2024-01-01 was a Monday
    return out;
  };
  const short = build("short");
  return Math.max(...short.map((s) => s.length)) > 4 ? build("narrow") : short;
}

function dpRender(calEl, startISO, endISO) {
  const year  = +calEl.dataset.dpYear;
  const month = +calEl.dataset.dpMonth;
  const DOW = dowLabels();
  const min = minDate();
  const monthLabel = new Date(year, month, 1)
    .toLocaleDateString(LOCALE[lang] || "en-GB", { month: "long", year: "numeric" });
  const firstDay = new Date(year, month, 1).getDay();
  const offset   = (firstDay + 6) % 7;
  const total    = new Date(year, month + 1, 0).getDate();

  let cells = "";
  for (let i = 0; i < offset; i++) cells += `<span class="bk-dp-empty"></span>`;
  for (let d = 1; d <= total; d++) {
    const iso = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    const dis = iso < min;
    if (dis) { cells += `<span class="bk-dp-cell is-dis">${d}</span>`; continue; }
    let cls = "bk-dp-cell";
    if (startISO && iso === startISO) cls += " is-sel is-start";
    if (endISO && iso === endISO) cls += " is-sel is-end";
    if (startISO && endISO && iso > startISO && iso < endISO) cls += " is-range";
    if (startISO && !endISO && iso === startISO) cls += " is-single";
    cells += `<button type="button" class="${cls}" data-role="dp-day" data-iso="${iso}">${d}</button>`;
  }

  const hint = startISO && !endISO ? `<div class="bk-dp-hint">${t("book.selectEnd")}</div>` : "";
  calEl.innerHTML = `
    <div class="bk-dp-head">
      <button type="button" class="bk-dp-nav" data-role="dp-prev">&#8249;</button>
      <span class="bk-dp-mth">${monthLabel}</span>
      <button type="button" class="bk-dp-nav" data-role="dp-next">&#8250;</button>
    </div>
    <div class="bk-dp-grid">
      ${DOW.map((d) => `<span class="bk-dp-dow">${d}</span>`).join("")}
      ${cells}
    </div>${hint}`;
}

function dpOpen(calEl, startISO, endISO) {
  const min = minDate();
  const ref = startISO && startISO >= min ? startISO : min;
  const d = new Date(ref + "T00:00:00");
  calEl.dataset.dpYear  = d.getFullYear();
  calEl.dataset.dpMonth = d.getMonth();
  dpRender(calEl, startISO || "", endISO || "");
  calEl.hidden = false;
}

function dateFieldVal(iso, ph) {
  return iso
    ? `<span class="bk-fb-val">${fmtField(iso)}</span>`
    : `<span class="bk-fb-val is-ph">${ph}</span>`;
}

/* live price row */
function priceRowHTML(b) {
  const days = stayDays(b);
  if (!days) {
    return `<div class="bk-price bk-price-empty">${t("book.priceHint")}</div>`;
  }
  const rate = ratePerDay(b.option, days);
  const psub = rate * days;
  const longNote = days >= LONG_STAY_DAYS ? ` <span class="bk-price-note">${t("book.longStay")}</span>` : "";
  // step 1 shows the parking price only — shuttle tickets are added on step 2
  return `<div class="bk-price">
    <div class="bk-price-line"><span>${optionName(b.option)} · ${money(rate)} × ${dayCountLabel(days)}${longNote}</span><span>${money(psub)}</span></div>
    <div class="bk-price-total"><span>${t("book.totalDue")}</span><strong>${money(psub)}</strong></div>
  </div>`;
}

/* small icon set for the glass pill fields */
function fieldIcon(name) {
  const P = {
    cal: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M3 9h18M8 2v4M16 2v4"/>',
    car: '<path d="M5 11l1.6-3.7A2 2 0 0 1 8.5 6h7a2 2 0 0 1 1.9 1.3L19 11"/><path d="M3.5 11h17a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1M4.5 16h-1a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1"/><circle cx="7.5" cy="16" r="1.7"/><circle cx="16.5" cy="16" r="1.7"/>',
    plate: '<rect x="2.5" y="6.5" width="19" height="11" rx="2"/><path d="M6 10.5v3M9.2 10.5v3M12.4 10.5v3M15.6 10.5v3M18.8 10.5v3"/>',
  };
  return `<svg class="bk-fb-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${P[name] || P.cal}</svg>`;
}
const CHEV = '<svg class="bk-fb-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>';

/* optional Zermatt Shuttle tickets — a toggle that reveals two compact steppers */
function ticketStepper(kind, qty) {
  return `<span class="bk-stepper">
    <button type="button" class="bk-step-btn" data-role="tq-dec" data-kind="${kind}" aria-label="${t("ui.decrease")}"${qty <= 0 ? " disabled" : ""}>&minus;</button>
    <span class="bk-step-qty">${qty}</span>
    <button type="button" class="bk-step-btn" data-role="tq-inc" data-kind="${kind}" aria-label="${t("ui.increase")}">+</button>
  </span>`;
}
function ticketsBlockHTML(b) {
  const row = (kind, name, price, qty) => `<div class="bk-ticket-row">
    <span class="bk-ticket-info"><span class="bk-ticket-name">${name}</span><span class="bk-ticket-price">${money(price)}</span></span>
    ${ticketStepper(kind, qty)}
  </div>`;
  return `<div class="bk-tickets${b.tickets ? " is-on" : ""}">
    <label class="bk-switch">
      <input type="checkbox" data-role="tickets-toggle"${b.tickets ? " checked" : ""}>
      <span class="bk-switch-track" aria-hidden="true"><span class="bk-switch-thumb"></span></span>
      <span class="bk-switch-text">
        <span class="bk-switch-title">${t("book.addTickets")}</span>
        <span class="bk-switch-sub">${t("book.ticketsInfo")}</span>
      </span>
    </label>
    ${b.tickets ? `<div class="bk-tickets-body">
      ${row("full", t("book.ticketFull"), TICKET_FULL, b.tFull || 0)}
      ${row("half", t("book.ticketHalf"), TICKET_HALF, b.tHalf || 0)}
      <p class="bk-ticket-note">${t("book.ticketDiscount")}</p>
    </div>` : ""}
  </div>`;
}

/* step 1 — glass booking card (Arrival / Departure / Option / Plate) */
function bookingFieldsHTML(b) {
  const optBtn = (opt, sub) => {
    const active = b.option === opt ? " is-active" : "";
    return `<button type="button" class="bk-opt${active}" data-role="opt" data-opt="${opt}" aria-pressed="${b.option === opt}">
      <span class="bk-opt-check" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></span>
      <span class="bk-opt-body"><span class="bk-opt-name">${optionName(opt)}</span><span class="bk-opt-sub">${sub}</span></span>
      <span class="bk-opt-price">${money(PRICE[opt].base)}<small>/${t("book.perDay")}</small></span>
    </button>`;
  };
  return `<div class="bk-vehicle" data-index="0">
    <div class="bk-grid2">
      <div class="bk-dp-wrap bk-daterow">
        <div class="bk-dates">
          <button type="button" class="bk-fieldbtn" data-role="dp-trigger">
            ${fieldIcon("cal")}
            <span class="bk-fb-body"><span class="bk-fb-label">${t("book.arrivalDate")} *</span>${dateFieldVal(b.start, t("book.periodPh"))}</span>
            ${CHEV}
          </button>
          <button type="button" class="bk-fieldbtn" data-role="dp-trigger">
            ${fieldIcon("cal")}
            <span class="bk-fb-body"><span class="bk-fb-label">${t("book.departureDate")} *</span>${dateFieldVal(b.end, t("book.periodPh"))}</span>
            ${CHEV}
          </button>
        </div>
        <div class="bk-dp-cal" data-role="dp-cal" hidden></div>
      </div>
      <div class="bk-optsfield">
        <span class="bk-opts-label">${t("book.chooseOption")} *</span>
        <div class="bk-opts">
          ${optBtn("parking", t("book.optParkingSub"))}
          ${optBtn("charging", t("book.optChargingSub"))}
        </div>
      </div>
      <label class="bk-fieldbtn bk-fieldinput">
        ${fieldIcon("plate")}
        <span class="bk-fb-body"><span class="bk-fb-label">${t("book.plate")} *</span>
          <input type="text" class="bk-fb-input" data-role="plate" placeholder="${t("book.platePlaceholder")}" value="${esc(b.plate)}"></span>
      </label>
    </div>
    <p class="bk-height-note">${t("book.maxHeight")}</p>
    ${priceRowHTML(b)}
  </div>`;
}

function renderStep1() {
  const total = parkingSubtotal(booking);   // tickets are added on step 2
  const cta = total > 0 ? `${t("book.continue")} · ${money(total)}` : t("book.continue");
  return `<div class="bk-cardhead">
      <span class="bk-cardhead-ic" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="17" height="17" rx="4.5"/><path d="M9 16.5V7.5h3.6a3 3 0 0 1 0 6H9"/></svg>
      </span>
      <h3 class="bk-cardhead-title">${t("book.cardTitle")}</h3>
    </div>
    <div class="bk-vehicles">${bookingFieldsHTML(booking)}</div>
    <button type="button" class="bk-cta" data-role="next">${cta}
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
    </button>`;
}

/* step 2 — Zermatt Shuttle tickets + contact e-mail */
function renderStep2() {
  const b = booking;
  const total = bookingTotal(b);
  return `${stepsHTML(2)}
    ${ticketsBlockHTML(b)}
    <div class="bk-grid bk-grid-1">
      <label class="bk-field"><span class="bk-label">${t("book.email")} *</span>
        <span class="bk-control"><input type="email" class="bk-input" data-bk="email" placeholder="${t("book.emailPh")}" value="${esc(b.email)}"></span></label>
    </div>
    <div class="bk-note">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v5"/><path d="M12 8h.01"/></svg>
      <p>${t("book.holderNote")}</p>
    </div>
    <div class="bk-bar">
      <button type="button" class="bk-back" data-role="back">${t("book.back")}</button>
      <button type="button" class="bk-continue" data-role="next">${t("book.continue")}${total > 0 ? ` · ${money(total)}` : ""}
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
      </button>
    </div>`;
}

/* step 3 — order summary, terms & pay */
function renderStep3() {
  const b = booking;
  const days = stayDays(b);
  const rate = ratePerDay(b.option, days);
  const total = bookingTotal(b);
  return `${stepsHTML(3)}
    <div class="bk-summary bk-summary-top">
      <div class="bk-summary-title">${t("book.orderSummary")}</div>
      <div class="bk-summary-row">
        <span>${optionName(b.option)}</span>
        <span>${days ? money(rate) + " / " + t("book.perDay") : "—"}</span>
      </div>
      <div class="bk-summary-row">
        <span>${fmtLong(b.start)} → ${fmtLong(b.end)}</span>
        <span>${days ? dayCountLabel(days) : "—"}</span>
      </div>
      <div class="bk-summary-row">
        <span>${t("book.plate")}</span>
        <span>${esc(plateLabel(b)) || "—"}</span>
      </div>
      ${(b.tickets && ticketsCount(b) > 0) ? `<div class="bk-summary-row">
        <span>${t("book.ticketsSummary")} · ${ticketsCount(b)}</span>
        <span>${money(ticketsTotal(b))}</span>
      </div>` : ""}
      <div class="bk-summary-total">
        <span>${t("book.totalDue")}</span>
        <span>${money(total)}</span>
      </div>
    </div>
    <label class="bk-check bk-check-terms"><input type="checkbox" data-bk="terms"${b.terms ? " checked" : ""}> ${t("book.terms")} *</label>
    <div class="bk-bar">
      <button type="button" class="bk-back" data-role="back">${t("book.back")}</button>
      <button type="button" class="bk-continue" data-role="pay">${t("book.pay")} · ${money(total)}</button>
    </div>`;
}

function renderBooking() {
  const html = bookStep === 3 ? renderStep3() : bookStep === 2 ? renderStep2() : renderStep1();
  document.querySelectorAll("#bkContent, #bkContent2").forEach((r) => { r.innerHTML = html; });
}

function onBookingChange(e) {
  const bk = e.target.dataset.bk;
  if (bk) {
    booking[bk] = bk === "terms" ? e.target.checked : e.target.value;
    const inv = e.target.closest(".bk-field") || e.target.closest(".bk-check");
    if (inv) inv.classList.remove("is-invalid");
    saveState();
    return;
  }
  const role = e.target.dataset.role;
  if (role === "plate") {
    booking.plate = e.target.value;
    const field = e.target.closest(".bk-fieldbtn") || e.target.closest(".bk-field");
    if (field) field.classList.remove("is-invalid");
    saveState();
  } else if (role === "tickets-toggle") {
    booking.tickets = e.target.checked;
    if (booking.tickets && (booking.tFull || 0) + (booking.tHalf || 0) === 0) booking.tFull = 1;
    renderBooking();
    saveState();
  }
}

function markInvalid1(root) {
  root.querySelectorAll(".bk-fieldbtn, .bk-field").forEach((f) => f.classList.remove("is-invalid"));
  const b = booking;
  if (!b.start || !b.end) {
    root.querySelectorAll('[data-role="dp-trigger"]').forEach((el) => {
      const f = el.closest(".bk-fieldbtn"); if (f) f.classList.add("is-invalid");
    });
  }
  if (!(b.plate && b.plate.trim())) {
    const el = root.querySelector('[data-role="plate"]');
    const f = el && el.closest(".bk-fieldbtn"); if (f) f.classList.add("is-invalid");
  }
}

function validateStep1(root) {
  if (!validBooking(booking)) {
    markInvalid1(root);
    toast(booking.start && booking.end ? t("book.msgIncomplete") : t("book.selectDates"));
    root.querySelector(".bk-vehicle").scrollIntoView({ behavior: "smooth", block: "center" });
    return false;
  }
  return true;
}

// step 2 → step 3 gate: a valid e-mail
function validateStep2(root) {
  const b = booking;
  const ctrl = root.querySelector('[data-bk="email"]');
  const ok = validEmail(b.email);
  const field = ctrl && ctrl.closest(".bk-field");
  if (field) field.classList.toggle("is-invalid", !ok);
  if (!ok) { toast(t("book.msgIncomplete")); if (field) field.scrollIntoView({ behavior: "smooth", block: "center" }); return false; }
  return true;
}

// step 3 → pay gate: the terms box must be ticked
function validateStep3(root) {
  const b = booking;
  const ctrl = root.querySelector('[data-bk="terms"]');
  const ok = !!b.terms;
  const field = ctrl && ctrl.closest(".bk-check");
  if (field) field.classList.toggle("is-invalid", !ok);
  if (!ok) { toast(t("book.msgIncomplete")); if (field) field.scrollIntoView({ behavior: "smooth", block: "center" }); return false; }
  return true;
}

function scrollCardIntoView(root) {
  const card = root ? (root.closest(".booking-card") || root.closest("section")) : document.querySelector("#book");
  if (card) card.scrollIntoView({ behavior: "smooth", block: "start" });
}

function onBookingClick(e) {
  const btn = e.target.closest("button[data-role]");
  if (!btn) return;
  const role = btn.dataset.role;

  if (role === "opt") {
    booking.option = btn.dataset.opt === "charging" ? "charging" : "parking";
    renderBooking();
    saveState();
    return;
  }
  if (role === "tq-inc" || role === "tq-dec") {
    const key = btn.dataset.kind === "half" ? "tHalf" : "tFull";
    let q = (booking[key] || 0) + (role === "tq-inc" ? 1 : -1);
    booking[key] = Math.max(0, Math.min(TICKET_MAX, q));
    renderBooking();
    saveState();
    return;
  }
  if (role === "dp-trigger") {
    const wrap = btn.closest(".bk-dp-wrap");
    const cal  = wrap.querySelector('[data-role="dp-cal"]');
    if (cal.hidden) {
      dpOpen(cal, booking.start, booking.end);
      setTimeout(() => {
        const close = (ev) => { if (!wrap.contains(ev.target)) { cal.hidden = true; document.removeEventListener("click", close, true); } };
        document.addEventListener("click", close, true);
      }, 0);
    } else {
      cal.hidden = true;
    }
    return;
  }
  if (role === "dp-prev" || role === "dp-next") {
    const cal = btn.closest('[data-role="dp-cal"]');
    let m = +cal.dataset.dpMonth, y = +cal.dataset.dpYear;
    if (role === "dp-prev") { m--; if (m < 0)  { m = 11; y--; } }
    else                    { m++; if (m > 11) { m = 0;  y++; } }
    cal.dataset.dpMonth = m; cal.dataset.dpYear = y;
    dpRender(cal, booking.start, booking.end);
    return;
  }
  if (role === "dp-day") {
    const iso = btn.dataset.iso;
    const cal = btn.closest('[data-role="dp-cal"]');
    if (!booking.start || (booking.start && booking.end)) {
      booking.start = iso; booking.end = "";
    } else if (iso < booking.start) {
      booking.start = iso; booking.end = "";
    } else {
      booking.end = iso;
    }
    saveState();
    if (booking.start && booking.end) {
      renderBooking();            // both chosen — rebuild form, calendar closes
    } else {
      dpRender(cal, booking.start, booking.end); // keep open for the end date
    }
    return;
  }
  if (role === "next") {
    const ok = bookStep === 2 ? validateStep2(e.currentTarget) : validateStep1(e.currentTarget);
    if (ok) { bookStep = Math.min(3, bookStep + 1); renderBooking(); scrollCardIntoView(e.currentTarget); saveState(); }
  } else if (role === "back") {
    bookStep = Math.max(1, bookStep - 1); renderBooking(); scrollCardIntoView(e.currentTarget); saveState();
  } else if (role === "pay") {
    // re-check the earlier steps as well: the card may have been restored or edited in the other widget
    const root = e.currentTarget;
    if (!validBooking(booking)) { bookStep = 1; renderBooking(); saveState(); validateStep1(root); return; }
    if (!validEmail(booking.email)) { bookStep = 2; renderBooking(); saveState(); validateStep2(root); return; }
    if (validateStep3(root)) {
      sendBookingEmail();
      showServiceError();
    }
  }
}

function initBooking() {
  const roots = document.querySelectorAll("#bkContent, #bkContent2");
  if (!roots.length) return;
  renderBooking();
  roots.forEach((root) => {
    root.addEventListener("input", onBookingChange);
    root.addEventListener("change", onBookingChange);
    root.addEventListener("click", onBookingClick);
  });
}

/* ---------- keep the hero photo still while the form is used ----------
   The hero's height follows its content and .hero-bg is height:100% with
   object-fit:cover, so every time the booking card grew (picking dates,
   opening the Zermatt Shuttle tickets block) the photo was re-scaled and
   visibly jumped. Pin the photo to the height the hero has on load, so the
   framing stays exactly as designed and the form can no longer resize it.
   Whatever the growing card uncovers below is filled by .hero::before, which
   carries the same photo. Only a new window size re-fits it. */
function lockHeroPhoto() {
  const hero = document.querySelector(".hero");
  const img = hero && hero.querySelector(".hero-bg");
  if (!hero || !img) return;

  img.style.height = "";        // measure against the stylesheet's own height:100%
  img.style.bottom = "";
  const h = hero.offsetHeight;  // the height the hero has on this screen

  img.style.bottom = "auto";    // inset:0 would otherwise fight an explicit height
  img.style.height = h + "px";
}

/* ---------- weather (live, Open-Meteo — no API key) — Zermatt / Matterhorn ---------- */
const WEATHER_URL =
  "https://api.open-meteo.com/v1/forecast?latitude=46.0207&longitude=7.7491" +
  "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max" +
  "&timezone=Europe%2FZurich&forecast_days=7";

let weatherData = null;

const WEATHER_SVG = {
  sun: '<svg viewBox="0 0 24 24" fill="none" stroke="#e3a52f" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4.4"/><path d="M12 2.6v2.3M12 19.1v2.3M4.6 4.6l1.6 1.6M17.8 17.8l1.6 1.6M2.6 12h2.3M19.1 12h2.3M4.6 19.4l1.6-1.6M17.8 6.2l1.6-1.6"/></svg>',
  partly: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><g stroke="#e3a52f"><circle cx="9" cy="8" r="3.1"/><path d="M9 2.4v1.5M3.4 8h1.5M4.9 3.9l1 1M13.1 3.9l-1 1"/></g><path fill="#fff" stroke="#8b9590" d="M8 19.5a3.6 3.6 0 0 1-.4-7.2 5 5 0 0 1 9.6-1.3 3.4 3.4 0 0 1-.2 8.5H8Z"/></svg>',
  cloud: '<svg viewBox="0 0 24 24" fill="#fff" stroke="#8b9590" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6.5 17.5a4.2 4.2 0 0 1-.5-8.4 5.9 5.9 0 0 1 11.3-1.5A4 4 0 0 1 17 17.5H6.5Z"/></svg>',
  fog: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff" stroke="#8b9590" d="M7 14.5a4 4 0 0 1-.5-8 5.6 5.6 0 0 1 10.8-1.4A3.8 3.8 0 0 1 16.7 14.5"/><path stroke="#9aa39e" d="M4.5 17.8h12M6.5 20.6h10"/></svg>',
  rain: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff" stroke="#8b9590" d="M7 15a4 4 0 0 1-.5-8 5.6 5.6 0 0 1 10.8-1.4A3.8 3.8 0 0 1 16.7 15H7Z"/><path stroke="#5b86a8" d="M8.5 17.4l-1 2.6M12 17.4l-1 2.6M15.5 17.4l-1 2.6"/></svg>',
  snow: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff" stroke="#8b9590" d="M7 15a4 4 0 0 1-.5-8 5.6 5.6 0 0 1 10.8-1.4A3.8 3.8 0 0 1 16.7 15H7Z"/><g fill="#6f97b5" stroke="none"><circle cx="8.5" cy="18.6" r=".75"/><circle cx="12" cy="19.8" r=".75"/><circle cx="15.5" cy="18.6" r=".75"/></g></svg>',
  storm: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff" stroke="#8b9590" d="M7 14.5a4 4 0 0 1-.5-8 5.6 5.6 0 0 1 10.8-1.4A3.8 3.8 0 0 1 16.7 14.5H7Z"/><path fill="#e3a52f" stroke="#e3a52f" stroke-width=".8" d="M12.4 15.5l-2.9 4h2.1l-.8 3 3.2-4.3h-2.2z"/></svg>',
};
const DROP_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3.6S6 10 6 14a6 6 0 0 0 12 0c0-4-6-10.4-6-10.4z"/></svg>';

function weatherIcon(code) {
  if (code === 0) return WEATHER_SVG.sun;
  if (code === 1 || code === 2) return WEATHER_SVG.partly;
  if (code === 3) return WEATHER_SVG.cloud;
  if (code === 45 || code === 48) return WEATHER_SVG.fog;
  if (code >= 71 && code <= 77) return WEATHER_SVG.snow;
  if (code >= 85 && code <= 86) return WEATHER_SVG.snow;
  if (code >= 95) return WEATHER_SVG.storm;
  if (code >= 51 && code <= 82) return WEATHER_SVG.rain;
  return WEATHER_SVG.cloud;
}

async function loadWeather() {
  const grid = document.querySelector("#weatherGrid");
  if (!grid) return;
  try {
    const res = await fetch(WEATHER_URL);
    if (!res.ok) throw new Error("HTTP " + res.status);
    weatherData = (await res.json()).daily;
    renderWeather();
  } catch (e) {
    weatherData = null;
    grid.innerHTML = '<p class="weather-msg">' + t("weather.error") + "</p>";
  }
}

function renderWeather() {
  const grid = document.querySelector("#weatherGrid");
  if (!grid || !weatherData) return;
  const d = weatherData;
  grid.innerHTML = d.time.map((iso, i) => {
    const date = new Date(iso + "T00:00:00");
    const isToday = i === 0;
    const name = isToday ? t("weather.today") : date.toLocaleDateString(LOCALE[lang], { weekday: "short" });
    const dnum = date.toLocaleDateString(LOCALE[lang], { day: "numeric", month: "short" });
    const max = Math.round(d.temperature_2m_max[i]);
    const min = Math.round(d.temperature_2m_min[i]);
    const pop = d.precipitation_probability_max[i] ?? 0;
    return (
      '<div class="wday' + (isToday ? " is-today" : "") + '">' +
        '<span class="wday-name">' + name + "</span>" +
        '<span class="wday-date">' + dnum + "</span>" +
        '<span class="wday-icon">' + weatherIcon(d.weather_code[i]) + "</span>" +
        '<span class="wday-temp">' + max + "°<small> / " + min + "°</small></span>" +
        '<span class="wday-precip">' + DROP_SVG + " " + pop + "%</span>" +
      "</div>"
    );
  }).join("");
}

/* ---------- toast ---------- */
let toastTimer;
function toast(msg) {
  const el = $("#toast");
  if (!el) return;
  el.textContent = msg;
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), 3400);
}

/* ---------- send booking to email ---------- */
async function sendBookingEmail() {
  const b = booking;
  const days = stayDays(b);
  const total = bookingTotal(b);

  const formData = new FormData();
  formData.append("_to", "cat.web@mail.ru");
  formData.append("_subject", `New Täsch Parking Booking - ${b.email}`);
  formData.append("_captcha", "false");

  const message = `BOOKING REQUEST — Täsch Parking

Contact:
- E-mail: ${b.email}

Parking:
- Option: ${optionName(b.option, "en")}
- Period: ${fmtLong(b.start, "en")} → ${fmtLong(b.end, "en")} (${days} day(s))
- Licence plate: ${plateLabel(b)}
- Rate: ${money(ratePerDay(b.option, days))} / day
- Parking subtotal: ${money(parkingSubtotal(b))}
${(b.tickets && ticketsCount(b) > 0) ? `
Zermatt Shuttle tickets (departure ${fmtLong(b.start, "en")}, return within 30 days):
- Adult (CHF ${TICKET_FULL}): ${b.tFull || 0}
- Reduced (CHF ${TICKET_HALF}): ${b.tHalf || 0}
- Tickets subtotal: ${money(ticketsTotal(b))}
` : ""}
Total: ${money(total)}

Submitted at: ${new Date().toLocaleString()}`;

  formData.append("message", message);

  try {
    await fetch("https://formsubmit.co/ajax/cat.web@mail.ru", {
      method: "POST",
      body: formData,
    });
    return true;
  } catch (e) {
    console.error("Email send failed:", e);
    return false;
  }
}

/* ---------- modal error ---------- */
function showServiceError() {
  const modal = document.createElement("div");
  modal.className = "modal-overlay";
  modal.innerHTML = `
    <div class="modal-dialog" role="dialog" aria-modal="true">
      <div class="modal-header">
        <h2>${t("book.serviceError")}</h2>
        <button class="modal-close" aria-label="${t("ui.close")}">&times;</button>
      </div>
      <div class="modal-body">
        <p>${t("book.serviceErrorMsg")}</p>
      </div>
      <div class="modal-footer">
        <button class="modal-btn" type="button">${t("book.back")}</button>
      </div>
    </div>
  `;
  const opener = document.activeElement;
  document.body.appendChild(modal);

  const openedAt = Date.now();
  const closeBtn = modal.querySelector(".modal-close");
  const backBtn = modal.querySelector(".modal-btn");
  const onKey = (e) => { if (e.key === "Escape") close(); };
  const close = () => {
    modal.remove();
    document.removeEventListener("keydown", onKey);
    if (opener && opener.isConnected) opener.focus();
  };
  closeBtn.addEventListener("click", close);
  backBtn.addEventListener("click", close);
  // the dialog appears under the pointer mid-click — ignore the second click of a double-click
  modal.addEventListener("click", (e) => { if (e.target === modal && Date.now() - openedAt > 400) close(); });
  document.addEventListener("keydown", onKey);
  backBtn.focus();
}

/* ---------- wiring ---------- */
function init() {
  loadState();

  // Language dropdown
  const langWrap = $("#lang");
  const langBtn = $("#langBtn");
  if (langBtn) langBtn.addEventListener("click", (e) => { e.stopPropagation(); toggleMenu(langWrap); });
  $$("#langMenu .select-option").forEach((li) => {
    li.tabIndex = 0;   // reachable with Tab while the menu is open (closed menus are visibility:hidden)
    const pick = (e, viaKey) => {
      e.preventDefault(); e.stopPropagation();
      setLang(li.dataset.lang); lockHeroPhoto();
      if (viaKey && langBtn) langBtn.focus();
    };
    li.addEventListener("click", (e) => pick(e, false));
    li.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") pick(e, true); });
  });

  // Global close
  document.addEventListener("click", closeMenus);
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeMenus(); });

  syncLangUI();
  applyI18n();
  applyMeta();
  syncLangUrl();
  loadWeather();
  initBooking();
  lockHeroPhoto();

  // web fonts land after DOMContentLoaded and nudge the hero's height, so take
  // the measurement again once everything has actually loaded
  window.addEventListener("load", lockHeroPhoto);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(lockHeroPhoto);

  // only a new window width may re-fit the hero photo — the form never does, and neither
  // do mobile browser toolbars collapsing on scroll (they change the height only)
  let heroFitTimer, heroFitWidth = window.innerWidth;
  window.addEventListener("resize", () => {
    if (window.innerWidth === heroFitWidth) return;
    heroFitWidth = window.innerWidth;
    clearTimeout(heroFitTimer);
    heroFitTimer = setTimeout(lockHeroPhoto, 150);
  });
}

document.addEventListener("DOMContentLoaded", init);
